-- 2. Leçons ----------------------------------------------------------------
INSERT INTO public.lessons (id, chapter_id, title, content, position) VALUES
  ('2e1bbe13-49f3-5dff-be7e-3ce00424c4a8', '9d54ed6e-8234-52d8-8672-caa4a6dea667', 'Une institution, pas un lieu', E'Un **marché** est le lieu — **réel ou non** — de rencontre entre une **offre** et une **demande**, d’où sortent un **prix** et une **quantité échangée**.\n\n> La Bourse, un site de petites annonces et le **marché du travail** sont des marchés **au même titre que la place du village**.\n\n## Le marché est une institution\nUn échange marchand suppose des **règles** — et **ces règles ne tombent pas du ciel**.\n\n| Règle nécessaire | Ce qu’elle permet |\n| Des **droits de propriété** définis et protégés | **On ne vend que ce qu’on possède** |\n| Une **monnaie** acceptée par tous | Elle évite le **troc** et sa **double coïncidence des désirs** |\n| Des **contrats** exécutoires | Garantis par la **justice** |\n| De l’**information** | Étiquetage, normes, garanties |\n\n> **Sans État de droit, pas de marché** : c’est l’**institution qui rend l’échange possible**, pas l’inverse.\n\n## Ce que le prix fait\nIl coordonne **des millions de décisions individuelles** sans qu’aucun bureau central ne les organise.\n\n| Rôle du prix | Ce qu’il fait |\n| Il **informe** | Une hausse dit que le produit **devient rare** |\n| Il **incite** | Elle pousse les producteurs à **en offrir davantage** |\n| Il **rationne** | Elle **écarte** les acheteurs qui n’en veulent pas à ce prix |\n\n## Les coûts de transaction\nÉchanger n’est **jamais gratuit** : chercher l’information, **négocier**, rédiger le contrat, le faire respecter.\n\n> Les **plateformes numériques**, les places de marché et les intermédiaires **vivent précisément de leur réduction**.\n\n## Marché et autres modes de coordination\n| Mode | Son ressort |\n| Le **marché** | Le **prix** |\n| La **hiérarchie** — entreprise, administration | L’**ordre** |\n| La **réciprocité** — don, entraide | L’**obligation sociale** |\n\n> Une économie réelle **mêle les trois**.', 1),
  ('08fc696a-95d3-561c-81cc-f4506a06e1c6', 'd2a9018d-a9dd-53bb-b458-242bfe7f4808', 'Offre, demande et prix d’équilibre', E'La **concurrence parfaite** est un **modèle** : **cinq conditions** y sont réunies.\n\n| Condition | Ce qu’elle exige |\n| **Atomicité** | Une **multitude** d’offreurs et de demandeurs |\n| **Homogénéité** | Le produit est **identique** partout |\n| **Libre entrée et sortie** | Aucune barrière |\n| **Information parfaite** | Tous savent tout |\n| **Libre circulation** des facteurs | Capital et travail se déplacent |\n\n## Les deux courbes\n| Courbe | Son sens | Pourquoi |\n| La **demande** | **Décroissante** | Plus le prix monte, **moins on achète** |\n| L’**offre** | **Croissante** | Plus le prix monte, **plus il est rentable de vendre** |\n\n> Leur **intersection** donne le **prix d’équilibre** : celui pour lequel **la quantité offerte égale la quantité demandée**.\n\n## Le retour à l’équilibre\n| Si le prix est… | Ce qui se passe |\n| **Trop élevé** | L’offre dépasse la demande : la **mévente** fait **baisser** le prix |\n| **Trop bas** | La **pénurie** fait **monter** les enchères |\n\n> Le marché s’ajuste **par les prix**. Et **aucun agent n’a de pouvoir** : chacun est *price taker*.\n\n## Le piège du devoir\n| La variation porte sur… | Ce qui se passe |\n| Le **prix du bien** | On se **déplace le long** de la courbe |\n| **Autre chose** — revenu, prix d’un substitut, goûts, coût, technologie | On **déplace la courbe entière** |\n\n> Une hausse du revenu des ménages **ne remonte pas la courbe de demande le long de son tracé** : elle la **décale vers la droite** — et le **nouveau prix d’équilibre est plus élevé**.\n\n## Le surplus\n| Surplus | Ce qu’il mesure |\n| Du **consommateur** | L’écart entre **ce qu’il était prêt à payer** et **ce qu’il paie** |\n| Du **producteur** | Entre le **prix reçu** et **le prix qu’il aurait accepté** |\n\n> Leur **somme** mesure le **gain à l’échange**.', 1),
  ('1beebc22-485f-5484-8653-a82cd17b6365', 'fe83dd47-a39c-5976-8aa3-0a598ff797a3', 'Monopole, oligopole et concurrence monopolistique', E'Dans la réalité, **une des cinq conditions manque presque toujours**. Le producteur cesse d’être **preneur de prix** : il devient **faiseur de prix** (*price maker*).\n\n## Les trois structures\n| Structure | Le nombre d’offreurs | Le produit |\n| **Monopole** | **Un seul** | — |\n| **Oligopole** | **Quelques-uns** | Souvent homogène |\n| **Concurrence monopolistique** | **Beaucoup** | **Différencié** |\n\n## Le monopole\n| Ce qu’il fait | Le résultat |\n| Il fixe son prix **au-dessus du coût marginal** | **Prix plus élevé**, **quantité plus faible** |\n| Il capte une part du surplus | Une partie du **surplus du consommateur lui est transférée** |\n\n| Sa source | L’exemple |\n| Un **brevet** | Le médicament protégé |\n| Le contrôle d’une **ressource** | Une mine unique |\n| Une **économie d’échelle** telle qu’un seul producteur est plus efficace | Le monopole **naturel** : les **rails**, les **réseaux d’eau** |\n\n## L’oligopole\nChacun **tient compte de ce que feront les autres** : c’est l’**interdépendance stratégique**.\n\n| Issue | Pour le consommateur |\n| La **guerre des prix** | **Bénéfique** |\n| L’**entente** (cartel) | **Interdite** — elle **reconstitue un monopole** |\n\n## La concurrence monopolistique\nChacun détient un **petit monopole sur sa variété**.\n\n| Différenciation | Son moyen |\n| **Objective** | Qualité, caractéristiques |\n| **Subjective** | **Marque**, image, **publicité** |\n\n> C’est **le cas le plus répandu** : restauration, vêtements, téléphonie.\n\n## Le pouvoir de marché\nLa capacité à fixer un prix **supérieur au coût marginal** : par l’**innovation**, la publicité, la fidélisation, la **taille** — ou par des **barrières à l’entrée**.\n\n> La **politique de la concurrence** surveille **trois choses** : les **ententes**, les **abus de position dominante**, les **concentrations**. Elle ne combat **pas la taille en soi**, mais **l’usage qui en est fait**.', 1),
  ('22b91e9f-60cb-530e-a219-841138b010a4', '7118e8be-6cb2-53c4-8e49-9984b72df615', 'Externalités, biens collectifs et asymétries d’information', E'Une **défaillance de marché** est une situation où la coordination marchande, **laissée à elle-même**, **n’aboutit pas** à une allocation efficace. **Trois cas** au programme.\n\n## Les externalités\nUne **externalité** existe quand l’action d’un agent **affecte le bien-être d’un autre sans compensation monétaire**.\n\n| Type | L’exemple | Ce que le marché fait |\n| **Négative** | La **pollution** d’une usine, dont le coût est supporté par les riverains | Prix **trop bas**, quantité **trop élevée** |\n| **Positive** | La **vaccination**, la recherche, l’apiculture voisine d’un verger | Le marché en produit **trop peu** |\n\n| Remède | Son principe |\n| La **taxe** | Le **pollueur-payeur** |\n| La **subvention** | Encourager l’externalité positive |\n| La **réglementation** | Interdire ou imposer |\n| Un **marché de droits à polluer** | Des **quotas échangeables** |\n\n## Les biens collectifs\n| Propriété | Ce qu’elle signifie |\n| **Non rival** | **Ma consommation n’empêche pas la vôtre** |\n| **Non excluable** | **On ne peut empêcher personne d’en profiter** |\n\nExemples : l’**éclairage public**, la **défense nationale**, un **phare**.\n\n> Comme personne ne peut être exclu, **chacun a intérêt à attendre que les autres paient** : c’est le **passager clandestin**. **Le marché ne les produit pas** — la puissance publique s’en charge, **financée par l’impôt**.\n\n## Les asymétries d’information\n| Quand | Le mécanisme | L’exemple |\n| **Avant** le contrat | La **sélection adverse** | **Akerlof** : sur le marché des voitures d’occasion, l’acheteur ne distinguant pas les bonnes des mauvaises **n’offre qu’un prix moyen** — les bons vendeurs **se retirent**, il ne reste que les *lemons* |\n| **Après** le contrat | L’**aléa moral** | Un **assuré tous risques devient moins prudent** |\n\n> Les remèdes tournent tous autour du **même principe** : **réduire l’écart d’information** — garanties, labels, certifications, contrôle technique, **franchise** d’assurance.', 1),
  ('06fc14d8-df5c-5a08-9c79-3b99dc268481', '5cb90b22-e562-5dd6-a744-4d7ae5f423a0', 'Besoin de financement, capacité de financement', E'Chaque année, un agent compare son **épargne** à son **investissement**.\n\n| Situation | Ce qu’elle signifie |\n| Épargne **supérieure** à l’investissement | Une **capacité de financement** |\n| Épargne **inférieure** | Un **besoin de financement** |\n\n## Qui est dans quelle situation\n| Agent | Sa position habituelle |\n| Les **ménages** | **Capacité** : ils épargnent plus qu’ils n’achètent de logements |\n| Les **entreprises** | **Besoin** : leurs investissements dépassent leurs profits non distribués |\n| Les **administrations publiques** | **Besoin** dès que le budget est **en déficit** |\n\n> La fonction du système financier tient en un mot : **transférer** les fonds des premiers vers les seconds.\n\n## L’autofinancement\nIl utilise l’**épargne déjà constituée** — pour une entreprise, les **bénéfices mis en réserve**.\n\n| Son avantage | Sa limite |\n| **Pas d’intérêts**, **pas de dilution du pouvoir** | Il est **limité par la taille des profits passés** |\n\n## Le financement externe\n| Forme | Comment ça marche |\n| **Direct** (de marché) | L’agent **émet un titre** acheté par l’épargnant, **sans intermédiaire décisionnaire** |\n| **Indirect** (intermédié) | Une **banque** prête, après avoir collecté des dépôts **ou créé de la monnaie** |\n\n> L’indirect finance **l’immense majorité des PME et des ménages**.\n\n## Action ou obligation\n| | **Action** | **Obligation** |\n| Sa nature | Un titre de **propriété** | Un titre de **créance** |\n| Ce qu’elle donne | Un **dividende** et un **droit de vote** | Un **intérêt** et le **remboursement** |\n| Son remboursement | **Elle ne se rembourse pas : elle se revend** | **À l’échéance** |\n\n> C’est la **distinction attendue en devoir**.', 1),
  ('905808c0-51a3-53d5-aa26-d97cdec70256', '7d12d9e7-ae33-5009-b0bf-7fa6498e7e7a', 'Le prix du temps et du risque', E'Le **taux d’intérêt** est le **prix du temps** : ce que l’emprunteur paie pour disposer **aujourd’hui** d’une somme qu’il rendra **demain** — et ce que le prêteur exige **pour y renoncer**.\n\n## Ce qui fait varier le taux\n| Facteur | Son effet |\n| La **durée** | Plus le prêt est long, **plus l’incertitude est grande**, plus le taux est élevé |\n| Le **risque de crédit** | La **prime de risque** : une entreprise fragile emprunte **plus cher** qu’un État solide |\n| Le **taux directeur** de la banque centrale | Il fixe le coût de refinancement des banques et **se répercute sur tous les taux** |\n\n## Taux nominal, taux réel\n**Taux réel ≈ taux nominal − taux d’inflation**\n\n| Une inflation forte | Qui elle avantage |\n| Elle **réduit le coût réel** d’un emprunt à taux fixe | L’**emprunteur** — au détriment du **prêteur** |\n\n> Emprunter à **3 %** quand les prix montent de **5 %**, c’est emprunter à un **taux réel négatif**.\n\n## Les deux marchés de capitaux\n| | **Marché primaire** | **Marché secondaire** |\n| Ce qui s’y passe | L’**émission** | La **revente entre investisseurs** |\n| L’émetteur | Il **lève effectivement des fonds** | Il **ne reçoit rien** |\n| Sa fonction | Le financement | Il rend les titres **liquides** |\n\n> **Sans la possibilité de revendre, personne n’achèterait sur le primaire.** C’est le lien à savoir énoncer.\n\n## Le rôle des banques\n| Métier | Ce qu’il fait |\n| **Collecter** | L’épargne |\n| **Transformer** | Des **dépôts courts** en **prêts longs** |\n| **Évaluer** | Le **risque de chaque emprunteur** |\n\n> Ce dernier travail, **le marché seul le fait mal** pour une **PME**.', 1),
  ('e03398e2-2627-58bf-b6bf-fe84ad6cb8eb', 'e7703ef6-4374-53b3-b279-299e795ea55e', 'Les formes de la monnaie', E'La monnaie est ce qui est **accepté par tous en règlement d’une dette**.\n\n> Sa valeur **ne tient pas à sa matière** mais à la **confiance** qu’elle inspire.\n\n## Trois formes\n| Forme | Ce qu’elle est | Sa place aujourd’hui |\n| **Marchandise** | Sel, bétail, métaux précieux : elle **vaut par ce qu’elle est** | Disparue |\n| **Fiduciaire** | Billets et pièces — de *fiducia*, la **confiance** : **le papier ne vaut rien en lui-même** | Une **petite part** de la masse monétaire |\n| **Scripturale** | De simples **écritures sur les comptes bancaires** | L’**essentiel** de la monnaie en circulation |\n\n## La confusion la plus fréquente\n> La **carte bancaire**, le **chèque** et le **virement** ne sont **pas de la monnaie** : ce sont des **instruments de circulation** de la monnaie scripturale.\n\n**La monnaie, c’est le solde du compte** — la carte n’est **qu’un moyen d’y toucher**.\n\n## Les trois piliers de la confiance\n| Pilier | Ce qu’il repose sur |\n| **Méthodique** | **Chacun l’accepte parce qu’il sait que les autres l’accepteront** |\n| **Hiérarchique** | Une **autorité** — banque centrale, État — en **garantit le cours légal** |\n| **Éthique** | Les **valeurs collectives** attachées à la **stabilité des prix** |\n\n> Quand la confiance s’effondre, la monnaie aussi : lors de l’**hyperinflation allemande de 1923**, **les billets valaient moins que le bois qu’ils servaient à remplacer dans les poêles**.\n\n## Et les cryptomonnaies ?\n| Fonction | Ce qu’elles font |\n| **Réserve de valeur** | **Trop volatiles** |\n| **Intermédiaire des échanges** | **Trop peu acceptées** |\n\n> Elles relèvent **davantage de l’actif spéculatif** que de la monnaie.', 1),
  ('1116538a-1336-5773-a8a9-64ff60eb099b', '0aaff9fd-9eff-514b-a43c-e0c60a59e950', 'Compter, échanger, conserver', E'Une monnaie se reconnaît **moins à ce qu’elle est qu’à ce qu’elle fait**. **Trois fonctions**, énoncées depuis **Aristote**.\n\n## Unité de compte\nElle donne une **mesure commune** de la valeur.\n\n| Sans unité de compte | Avec |\n| Il faudrait le prix de chaque bien **dans chaque autre bien** : pour 100 biens, **4 950 prix relatifs** | **100 prix suffisent** |\n\n> C’est un **gain d’information colossal**.\n\n## Intermédiaire des échanges\nElle brise le **troc** et sa **double coïncidence des désirs**.\n\n> Il ne suffisait pas de trouver quelqu’un **qui a ce que je veux** : il fallait aussi **qu’il veuille ce que j’ai**.\n\n> La monnaie **coupe l’échange en deux** : **je vends, puis j’achète** — à qui je veux, quand je veux.\n\n## Réserve de valeur\nElle permet de **différer** un achat : le pouvoir d’achat gagné aujourd’hui **se conserve pour demain**.\n\n| Sa fragilité | Le chiffre |\n| L’**inflation** l’érode | **5 % par an** ampute d’environ **un tiers** le pouvoir d’achat d’une somme conservée **sept ans** |\n\n> C’est **parce que la monnaie est une réserve de valeur** qu’on peut la **thésauriser** — **Keynes** en fait le motif de la **préférence pour la liquidité**.\n\n## Les agrégats monétaires\nClassés par **liquidité décroissante** par la Banque centrale européenne.\n\n| Agrégat | Ce qu’il contient |\n| **M1** | Pièces, billets et **dépôts à vue** — **immédiatement disponibles** |\n| **M2** | M1 **plus** les dépôts à court terme (livrets) |\n| **M3** | M2 **plus** les titres d’organismes de placement à court terme |', 1),
  ('40fc73bf-8453-51aa-b3ca-fa36cf466d92', 'c4f89b0f-13bf-502a-963f-b7e88916c1c1', 'Les crédits font les dépôts', E'La monnaie **n’est pas prélevée sur un stock existant** : elle est **créée** par un **jeu d’écritures**, chaque fois qu’une banque commerciale accorde un crédit.\n\n## Le mécanisme\n| Ce que fait la banque | Où |\n| Elle inscrit une **créance** | À son **actif** |\n| Elle **crédite le compte** du client | À son **passif** |\n\n> Cette somme **n’existait nulle part une seconde plus tôt**. **Les crédits font les dépôts**, et non l’inverse.\n\n> Symétriquement, **tout remboursement détruit de la monnaie**.\n\n## Les trois sources\n| Source | Sa part |\n| Le **crédit à l’économie** | **De loin la principale** |\n| L’achat de **devises** contre euros | Secondaire |\n| Le financement du **Trésor public** | Encadré |\n\n## Les limites\n| Limite | Ce qu’elle impose |\n| Les **fuites** | Une partie des sommes prêtées **quitte la banque** — retraits en billets, virements — et doit être couverte en **monnaie centrale** |\n| Les **réserves obligatoires** | Déposées à la banque centrale |\n| Les **ratios prudentiels** — Bâle III | Des **fonds propres proportionnés aux risques** |\n| La **demande de crédit** | Une banque **ne prête pas si personne n’emprunte** — ni si l’emprunteur **ne semble pas solvable** |\n\n## La banque centrale\n> Elle **ne crée pas la monnaie que nous utilisons au quotidien** : elle crée la **monnaie centrale**, **celle qui circule entre les banques**.\n\n| Son instrument | Ce qu’il fait |\n| Le **taux directeur** | Le coût du **refinancement** des banques |\n| Les **réserves obligatoires** | Elles bornent la création |\n| L’**open market** et, depuis 2015, les **achats massifs de titres** | Ils pilotent les taux longs |\n\n> Son objectif principal, dans la zone euro : la **stabilité des prix** — une inflation **proche de 2 %** à moyen terme.', 1),
  ('7927e1b3-223f-5d36-9989-04f0abdcb5ba', '0ad4ab27-2baa-59e9-904d-da23069a7258', 'Devenir un être social', E'La **socialisation** est le processus par lequel un individu **apprend et intériorise** les **normes**, les **valeurs** et les **rôles** de sa société.\n\n> **On ne naît pas social : on le devient.**\n\n## Trois notions à distinguer\n| Notion | Sa définition | L’exemple |\n| Une **valeur** | Un **idéal partagé** | L’égalité, la réussite, la solidarité |\n| Une **norme** | La **règle concrète** qui traduit une valeur | Ne pas couper la parole, respecter la file |\n| Un **rôle** | Le **comportement attendu** de celui qui occupe une position | L’élève, le parent, le médecin |\n\n## Les instances de socialisation\n| Instance | Ce qu’elle transmet |\n| La **famille** | La **première**, la plus **durable** : le langage, les manières de table, le rapport au corps et à l’argent |\n| L’**école** | Des savoirs — **et des dispositions** : ponctualité, effort, respect de la **règle impersonnelle** |\n| Les **pairs** | Décisifs à l’**adolescence** : ils imposent leurs codes, **parfois contre ceux de la famille** |\n| Les **médias** et réseaux sociaux | Des **modèles** |\n\n## Comment on socialise\n| Mode | Ce qu’il suppose |\n| L’**inculcation** explicite | On énonce la règle, on **récompense**, on **sanctionne** |\n| L’**imitation** | L’enfant **reproduit** ce qu’il observe |\n| L’**interaction** | L’enfant **n’est pas passif** : il **négocie, résiste, réinterprète** |\n\n> **Bourdieu** appelle **habitus** l’ensemble des **dispositions durables** ainsi **incorporées** : elles orientent goûts, gestes et choix **sans que l’individu ait à y penser**.\n\n## Une socialisation différenciée\n> Elle **ne produit pas des individus identiques** : selon le **milieu social** et le **genre**, **les mêmes instances transmettent des contenus différents**.', 1),
  ('ecaed378-ef4e-536a-b307-15a279aa1bec', '11fcea04-d4d3-5613-b399-56bd45aa86ea', 'Ce que l’enfance dépose, ce que la vie adulte remanie', E'La socialisation **ne s’arrête pas à l’enfance** — mais elle **ne s’y poursuit pas non plus à l’identique**.\n\n## Les deux socialisations\n| | **Primaire** | **Secondaire** |\n| Quand | Enfance et adolescence | Âge adulte |\n| Son étendue | **Globale** : du langage aux émotions | **Spécialisée** : un domaine |\n| Son ressort | **Affective** : elle passe par l’**attachement** | Plus **négociée** |\n| L’individu | Il **subit** davantage | Il est plus **actif** : **il choisit souvent le groupe qui va le socialiser** |\n| Sa force | **Durable** : appris comme **allant de soi** | Elle **se dépose dessus** |\n\nLes univers de la secondaire : le **travail**, le **couple**, la **parentalité**, un parti, une équipe, une communauté religieuse.\n\n## Continuité ou rupture\n| Cas | Ce qui se passe |\n| Le plus souvent | La seconde **prolonge** la première : on épouse dans son milieu, on choisit un métier compatible |\n| Parfois | Elle la **contredit** : mobilité sociale, **conversion**, **institution totale** — d’où une **resocialisation** |\n| Le terme | **Berger et Luckmann** parlent d’**alternation** : la nouvelle socialisation doit **d’abord démolir l’ancienne** |\n\n## La socialisation anticipatrice\n**Merton** l’a montrée : on peut **intérioriser les normes d’un groupe auquel on n’appartient pas encore**, **dans l’espoir de le rejoindre**.\n\n| Ce qu’elle facilite | Ce qu’elle risque |\n| La **mobilité** | Elle laisse **en porte-à-faux** celui qui **n’est finalement pas admis** |\n\n> La socialisation secondaire **ne remplace pas la primaire** : elle **se dépose dessus** — et les **conflits entre les deux** sont **le lot ordinaire des trajectoires improbables**.', 1),
  ('3401b787-8415-5d59-ba6b-7fa1d1057f92', '8c2a65d3-4e66-583c-8536-67133f8b1298', 'Le genre, le milieu social, et les exceptions', E'Si la socialisation explique les comportements, c’est parce qu’elle **diffère** selon la position sociale. **Deux différenciations** au programme.\n\n## La socialisation genrée\nDès la naissance, filles et garçons **ne reçoivent pas le même traitement**.\n\n| Différence | Le détail |\n| Les **couleurs** et les **jouets** | Un univers séparé |\n| Le **vocabulaire** | Un même comportement dit « **vive** » ou « **turbulent** » |\n| La **tolérance à la prise de risque** | Inégale |\n| Les **encouragements scolaires** | Distincts |\n\n> Ces différences **n’ont rien de naturel** : elles produisent des **dispositions** qui pèsent sur l’**orientation**, le **choix du métier**, le **partage des tâches domestiques**.\n\n> **Les filles réussissent mieux à l’école** que les garçons **et s’orientent pourtant moins** vers les filières scientifiques les mieux rémunérées : **c’est la socialisation, non l’aptitude, qui explique l’écart**.\n\n## La socialisation de classe\n| Ce qui varie avec le milieu | Ce que cela produit |\n| Le rapport au **langage** | Élaboré et **abstrait**, ou **pratique** et contextuel |\n| Le rapport au **temps** et à l’avenir | Il rend le **calcul scolaire** plus ou moins évident |\n| Les **pratiques culturelles** | Elles **rapprochent ou éloignent** de la culture valorisée par l’école |\n\n> C’est ce que Bourdieu appelle le **capital culturel** : un **héritage invisible**, **que l’école récompense sans l’avoir transmis**.\n\n## Les trajectoires improbables\n| Ce sur quoi elles reposent souvent | L’exemple |\n| Une **configuration familiale** particulière | Une mère qui **investit massivement la scolarité**, un frère aîné qui **ouvre la voie** |\n| Une **rencontre** décisive | Un enseignant |\n| Une **socialisation anticipatrice** réussie | Les codes adoptés à temps |\n\n> Elles **ne réfutent pas la sociologie** : elles rappellent que la socialisation produit des **probabilités**, **non des destins**.\n\n> **Un déterminisme statistique n’est pas une fatalité individuelle.**', 1),
  ('c4f6a4ea-d239-57c1-871e-361de3a1e942', '48ac32b6-7761-5218-b3f9-2f8bf0da76f4', 'Groupe social, agrégat, catégorie statistique', E'Toute réunion d’individus **n’est pas un groupe social**. **Trois notions** à ne **jamais confondre** en devoir.\n\n| Notion | Ce qu’elle suppose | L’exemple |\n| Le **groupe social** | Des **interactions**, un **sentiment d’appartenance**, une **reconnaissance par les autres** | Une famille, une équipe, une association |\n| L’**agrégat physique** | Le **même endroit**, **sans lien** | Les voyageurs d’un wagon, une file d’attente |\n| La **catégorie statistique** | Un **caractère mesurable** commun, **sans se connaître** | Les gauchers, les 15-24 ans, les cadres |\n\n> Une **catégorie statistique peut devenir un groupe social** si ses membres **prennent conscience de ce qu’ils ont en commun** et **s’organisent** : c’est le passage marxiste de la « **classe en soi** » à la « **classe pour soi** ».\n\n## Primaire ou secondaire — Cooley\n| | **Groupe primaire** | **Groupe secondaire** |\n| Sa taille | **Restreint** | Plus **vaste** |\n| Ses relations | **Directes, durables, affectives** | **Formelles et fonctionnelles** |\n| Son but | Aucun en particulier | **Orienté vers un but** |\n| L’exemple | Famille, bande d’amis | Entreprise, syndicat, parti |\n\n## Formel ou informel\n| | **Formel** | **Informel** |\n| Ce qu’il a | Statuts, **règles écrites**, hiérarchie explicite | Des **affinités** et de l’**implicite** |\n\n> **Les deux coexistent dans la même organisation** : les « **bandes** » d’un atelier sont informelles, **l’organigramme est formel**.\n\n## Pourquoi on s’associe\n| Motif | Ce qu’il apporte |\n| L’**intérêt** | Des **ressources** qu’on n’obtiendrait pas seul |\n| L’**affinité** — l’**homophilie** | **On s’associe à ceux qui nous ressemblent** : âge, milieu, goûts |\n| L’**héritage** | **On ne choisit ni sa famille ni son quartier d’enfance** |', 1),
  ('d6be81ab-7648-5ea4-b038-3b88c2ea5e50', '23b9cdc0-0e08-539f-9c66-32f3429dca9c', 'Celui auquel on appartient, celui auquel on aspire', E'Un individu **appartient à plusieurs groupes à la fois** — et **n’adopte pas forcément les normes de ceux auxquels il appartient**.\n\n## Appartenance et référence\n| | **Groupe d’appartenance** | **Groupe de référence** (Merton) |\n| Ce qu’il est | Celui dont on **fait effectivement partie** | Celui dont on **emprunte les normes pour se juger** |\n| La condition | L’appartenance | **Qu’on en fasse partie ou non** |\n\n| Quand les deux diffèrent | L’exemple |\n| L’individu vit un **décalage** | L’étudiant **boursier** qui adopte les codes des grandes écoles |\n| — | L’adolescent qui prend pour modèle **un groupe qu’il ne fréquente pas encore** |\n\n> C’est le terrain de la **socialisation anticipatrice**.\n\n## Les quatre liens sociaux\n| Lien | Ce qu’il recouvre |\n| De **filiation** | La famille |\n| De **participation élective** | Les amis, le couple, les associations **choisies** |\n| De **participation organique** | Le **travail**, la division du travail |\n| De **citoyenneté** | L’appartenance **politique** |\n\n> Ils **n’ont pas disparu** : ils se sont **transformés** — plus **électifs** (on choisit davantage), plus **réversibles** (ils se défont plus facilement), plus **nombreux** mais souvent **moins intenses**.\n\n## La sociabilité\nL’ensemble des relations **effectivement entretenues**. Elle est **socialement inégale**.\n\n| Milieu | La forme de sa sociabilité |\n| **Populaire** | De **voisinage** et de **famille** |\n| **Favorisé** | **Associative et amicale**, **plus étendue géographiquement** |\n\nElle **croît avec le diplôme et le revenu** — mais c’est sa **forme** qui change le plus.\n\n> L’**isolement relationnel** touche d’abord les **personnes âgées**, les **chômeurs de longue durée** et les personnes en **précarité** : **le lien social se défait avec l’emploi**.', 1),
  ('df58fb60-f0e8-59c8-98c8-b7787ea946e2', '8e8ae84a-1cf4-5236-90e3-a5ce5accddaf', 'La force des liens faibles', E'Un **réseau social** est l’ensemble des relations qui relient un individu à d’autres.\n\n> Il ne s’agit **pas d’abord des plateformes numériques** : **la sociologie des réseaux est antérieure à leur apparition**.\n\n## Liens forts, liens faibles — Granovetter, 1973\n| | **Liens forts** | **Liens faibles** |\n| Qui | Famille proche, amis intimes | Connaissances, anciens collègues, **amis d’amis** |\n| Leur nombre | **Peu nombreux** | **Nombreux** |\n| Leur ton | **Chaleureux** | **Distants** |\n| Leur information | **Redondante** : ces personnes **se connaissent entre elles** | Ils **relient des mondes séparés** |\n\n> La découverte contre-intuitive : **la plupart des emplois se trouvent par des liens faibles**. **L’information neuve vient de ceux qu’on connaît mal.**\n\n## Le capital social\nL’ensemble des **ressources auxquelles un individu accède grâce à son réseau**.\n\n| Sa propriété | Le détail |\n| Il est **inégalement réparti** | Les **cadres** ont des réseaux **plus étendus, plus diversifiés, mieux placés** que les ouvriers |\n| Il se **convertit** | Un réseau peut valoir **un emploi, un stage, un logement** |\n\n## Ce que les plateformes changent\n| Ce qu’elles apportent | Ce qu’elles n’abolissent pas |\n| Elles **élargissent le nombre de liens faibles** | L’**homophilie** y règne **autant qu’ailleurs** |\n| Elles **abaissent le coût de leur entretien** | Les **algorithmes de recommandation renforcent l’entre-soi** |\n| — | Elles créent de **nouvelles asymétries** : la **visibilité y est très concentrée** |\n\n## Réseau et action collective\nUn réseau **dense** **facilite la mobilisation** : il **fait circuler l’information**, exerce une **pression au conformisme** et **réduit le coût de l’engagement**.\n\n> C’est l’un des mécanismes qui **limite le comportement de passager clandestin** décrit par **Olson**.', 1),
  ('e28fa6fd-9e5e-54b8-b863-db31937ae571', '40c3daf5-4b70-50c5-8c42-c33db78145c6', 'Contrôle formel, contrôle informel', E'Le **contrôle social** est l’ensemble des moyens par lesquels une société obtient de ses membres qu’ils **respectent ses normes**. **Il ne se réduit pas à la police.**\n\n## Deux formes\n| | **Formel** | **Informel** |\n| Qui l’exerce | Des **institutions spécialisées** : police, justice, administration, inspection du travail | L’**entourage** : famille, voisins, collègues, pairs |\n| Comment | Selon des **règles écrites** | Par le **regard**, la **moquerie**, la réprobation, l’**exclusion** |\n| Sa sanction | **Codifiée** | **Diffuse** — mais **souvent plus efficace** |\n\n> Le contrôle **le plus puissant** est celui qu’on **exerce sur soi-même** : les **normes intériorisées** lors de la socialisation **évitent la plupart des transgressions sans qu’aucune sanction n’intervienne**.\n\n## Une évolution en deux temps\n| Mouvement | Ce qui se passe |\n| **Recul** du contrôle informel de proximité | L’**exode rural**, l’**anonymat urbain** et la **mobilité** ont affaibli le contrôle du village et du voisinage |\n| **Montée** du contrôle formel et technologique | **Vidéosurveillance**, **traçage numérique**, contrôle automatisé de la vitesse, données de connexion |\n\n> Le contrôle devient **permanent, distant et invisible**.\n\n## Le débat\n> Jusqu’où une société peut-elle **surveiller sans porter atteinte aux libertés** ?\n\n| Encadrement | Son échelle |\n| La **CNIL** | La France |\n| Le **RGPD** | L’Europe |\n\n## Contrôle et déviance\n> Le contrôle social ne se contente pas d’**empêcher** la déviance : **il la définit**.\n\nUne **même conduite** est déviante ou non **selon la société, l’époque et le groupe qui juge** : le **tabac**, le **duel**, l’**homosexualité** ont **changé de statut normatif**.', 1),
  ('a7ee48e3-d395-5620-9097-b4c5f7b15cbd', 'ce4a2bc5-d848-580a-b29c-54d2a5d9ed15', 'Anomie, étiquetage, carrière déviante', E'Transgresser une norme sociale, ce n''est pas la même chose que transgresser la loi.\n\n## Deux mots à ne pas confondre\n| Le mot | Ce qu''il transgresse | Portée |\n| **Déviance** | Une **norme sociale**, quelle qu''elle soit | Large |\n| **Délinquance** | Une **norme juridique** pénalement sanctionnée | Étroite |\n\n> Toute délinquance est déviante. L''inverse est faux.\n\n## L''explication par l''anomie\n| L''auteur | Sa thèse |\n| **Durkheim** | L''**anomie** est l''affaiblissement des normes collectives : quand la société ne régule plus les aspirations, les conduites se dérèglent |\n| **Merton** | La déviance naît de l''écart entre les **buts** valorisés (la réussite) et les **moyens légitimes** d''y accéder, inégalement distribués |\n\nLes cinq adaptations de Merton :\n1. **Conformité** — les buts et les moyens légitimes.\n2. **Innovation** — le but, mais par des moyens illégitimes.\n3. **Ritualisme** — les moyens sans le but.\n4. **Évasion** — ni l''un ni l''autre.\n5. **Rébellion** — d''autres buts et d''autres moyens.\n\n## L''explication par l''étiquetage\nBecker renverse la perspective : la déviance n''est pas une qualité de l''acte, mais le **produit de la réaction sociale**.\n\n| L''étape de la carrière déviante | Ce qui se passe |\n| La transgression initiale | Un acte, souvent banal |\n| La **réaction sociale** | Le groupe étiquette |\n| La **stigmatisation** | Les portes de la vie ordinaire se ferment |\n| L''entrée dans un groupe déviant | Il fournit à son tour des normes |\n\n> « Le déviant est celui auquel l''étiquette a été appliquée avec succès. » L''étiquette produit ce qu''elle prétend décrire : c''est une **prophétie auto-réalisatrice**.\n\n## Ce que cela change\n| L''approche | Ce qu''elle explique | La politique qui en découle |\n| **Merton** | Pourquoi certaines positions exposent à la transgression | Agir sur les inégalités d''accès aux moyens |\n| **Becker** | Pourquoi le traitement social aggrave la transgression | Éviter la stigmatisation précoce des mineurs |\n\n> Les deux ne s''opposent pas : elles décrivent deux moments différents.', 1),
  ('f1cf4c1d-e318-59f2-91b3-7b7cf03f78e8', '6ac8a48f-266f-546b-809a-04e78c2cff76', 'Statistiques policières, enquêtes de victimation, chiffre noir', E'Compter la délinquance est un problème de méthode avant d''être un débat politique.\n\n## Trois sources, aucune parfaite\n| La source | Ce qu''elle compte | Sa limite principale |\n| **Statistiques administratives** | Les plaintes enregistrées, les condamnations | Seulement ce qui est **déclaré** |\n| **Enquêtes de victimation** | Les atteintes **subies**, déclarées ou non | Reposent sur le **souvenir** de l''enquêté |\n| **Chiffre noir** | L''écart entre les deux | Par définition, il ne se mesure pas directement |\n\n## Les statistiques administratives\nElles dépendent d''autre chose que de la délinquance elle-même :\n- de l''**activité des services** — plus de contrôles routiers, ce sont mécaniquement plus d''infractions constatées ;\n- des **changements de législation** et de nomenclature, un acte pouvant entrer ou sortir du champ pénal ;\n- de la **propension à porter plainte**, très variable selon l''infraction.\n\n## Les enquêtes de victimation\nOn interroge un échantillon représentatif sur les atteintes subies : en France, l''enquête *Cadre de vie et sécurité*, puis *Vécu et ressenti en matière de sécurité*.\n\nElles font apparaître ce que les plaintes manquent, mais couvrent mal les infractions **sans victime directe** : trafic, corruption, fraude fiscale.\n\n## Le chiffre noir\n| L''infraction | Son chiffre noir | Pourquoi |\n| Vol de voiture | Très **faible** | La plainte est exigée par l''assurance |\n| Violences intrafamiliales et sexuelles | Très **élevé** | Honte, peur, dépendance à l''agresseur |\n\n> Une hausse des plaintes peut signaler une hausse des violences… ou une meilleure prise de parole des victimes. Les deux lectures s''appuient sur le même chiffre.\n\n## Un traitement pénal sélectif\nLa population carcérale est très majoritairement **jeune**, **masculine** et issue des **milieux populaires**. Ce constat mêle deux choses : des expositions différentes à la transgression, et un filtre pénal lui-même inégal — la délinquance en col blanc est moins détectée et moins sanctionnée.', 1),
  ('fd049100-60eb-5e56-bfee-1870fdcb1db5', '742a838c-91bf-50ad-acc0-f2b110921aaf', 'Des salons aux sondages', E'L''opinion publique n''est pas une donnée naturelle : c''est une construction historique.\n\n## Une définition\nL''**opinion publique** désigne l''ensemble des jugements partagés par une population sur les affaires communes.\n\n## Une histoire\n| L''époque | Le lieu de l''opinion |\n| **XVIIIe siècle** | Salons, cafés, presse : l''**espace public** décrit par Habermas |\n| **XIXe et XXe siècles** | Alphabétisation, presse de masse, puis radio et télévision |\n| **Aujourd''hui** | Réseaux sociaux : chacun peut publier, mais la visibilité reste très inégale |\n\n## Le sondage\nInstrument dominant depuis Gallup, en 1936. Il repose sur un **échantillon représentatif**, construit le plus souvent par la **méthode des quotas**, et donne un résultat assorti d''une **marge d''erreur**.\n\n| La limite | L''effet produit |\n| La **formulation** de la question | Elle oriente la réponse |\n| L''**ordre** des questions | Il crée des effets de contexte |\n| Les **non-réponses** | Elles masquent l''absence d''opinion réelle |\n| La **marge d''erreur** oubliée | Un écart minime est lu comme une différence |\n\n> Bourdieu, en 1973 : « L''opinion publique n''existe pas » — non pour nier les opinions, mais pour contester trois postulats : que tout le monde a un avis sur tout, que toutes les opinions se valent, et qu''il existe un accord sur les questions qui méritent d''être posées.\n\n## Sondage et démocratie : deux lectures\n| La lecture | Son argument |\n| Le sondage **éclaire** | Il donne la parole à ceux qu''on n''entend pas d''ordinaire |\n| Le sondage **fabrique** | Il impose l''agenda et produit des effets sur le vote : effet *bandwagon*, vote utile |', 1),
  ('267044db-e4d5-5f16-84dd-20b7329e902d', '8335e465-d9cf-5b0c-8fab-8cb5c8e4d8bb', 'Variables lourdes, vote sur enjeux, abstention', E'Le vote est un acte individuel et secret, mais il obéit à des régularités sociales mesurées depuis les années 1940.\n\n## Les variables lourdes\n| La variable | Ce qu''elle recouvre |\n| L''**appartenance de classe** | Profession, diplôme, patrimoine |\n| La **religion** | La pratique régulière reste l''une des plus prédictives |\n| Le **lieu de résidence** | Son effet s''est renforcé avec la géographie sociale |\n\nL''**âge**, le **genre** et la **socialisation politique familiale** complètent le tableau.\n\n> Lazarsfeld montrait dès 1944 que le vote se prédisait mieux par ces variables que par les campagnes elles-mêmes.\n\n## Leur affaiblissement\n| La cause | La conséquence |\n| Recul de la pratique religieuse | Une variable qui pèse moins |\n| Brouillage des frontières de classe | Des blocs électoraux moins nets |\n| Affaiblissement des partis de masse | Moins d''encadrement du vote |\n\nL''électeur est devenu plus **volatil** : il change de vote d''une élection à l''autre. Deux logiques nouvelles apparaissent :\n- le **vote sur enjeux**, qui privilégie un problème du moment ;\n- le **vote sur bilan**, qui sanctionne ou récompense les sortants.\n\n## L''abstention\n| Sa forme | Qui s''abstient | Pourquoi |\n| **Hors du jeu** | Les plus éloignés du système politique | Faible diplôme, précarité, isolement |\n| **Dans le jeu** | Des électeurs politisés | Protestation, ou absence d''offre satisfaisante |\n\nElle varie fortement selon le **type de scrutin** — forte aux européennes et aux locales, plus faible à la présidentielle — et selon l''**âge**, les jeunes votant beaucoup plus par intermittence.\n\n> Le vote reste un acte **socialement encouragé** : la sociabilité, la mobilisation par l''entourage et l''inscription associative augmentent nettement la participation.', 1),
  ('af377643-2efe-5843-bc5d-f7fa6776d925', 'f7d3664a-c895-5cb6-aafe-be00d06b7d1b', 'Risque, mutualisation, protection sociale', E'Un risque est un événement incertain aux conséquences dommageables. Les sociétés développées l''affrontent par la mutualisation.\n\n## Les risques et leur partage\nMaladie, accident, chômage, vieillesse, dépendance : la **mutualisation** consiste à partager le coût entre un grand nombre, pour qu''aucun ne le supporte seul.\n\n## Deux logiques de protection\n| La logique | Son principe | Son financement | Un exemple français |\n| **Assurance** (bismarckienne) | On cotise, on est couvert à proportion | Cotisations sociales | Retraites, assurance chômage |\n| **Assistance** (beveridgienne) | Prestation sous **condition de ressources** | Impôt | RSA |\n\n> Le système français est **hybride** : construit en 1945 sur une base assurantielle, il s''est élargi à mesure que la CSG a pris la place des cotisations.\n\n## Les acteurs\nLa protection sociale n''est pas seulement publique. Elle mêle :\n- la **Sécurité sociale** ;\n- les **mutuelles** et les **assurances privées** ;\n- les **associations** ;\n- la **famille**, qui reste pour la dépendance et la garde des enfants un producteur majeur de protection.\n\n## Les limites\n| La limite | Ce qu''elle décrit | La réponse |\n| **Aléa moral** | Être couvert peut réduire la prudence ou l''effort | Franchises, délais de carence, dégressivité |\n| **Sélection adverse** | Dans une assurance facultative, les bons risques partent, la prime monte | **Obligation** d''affiliation |\n| **Coût** | Environ un tiers du PIB français | Question du financement dans une population vieillissante |\n\n> Prélèvements et prestations réduisent fortement les inégalités : l''écart entre les revenus des 10 % les plus aisés et des 10 % les plus modestes est près de deux fois plus faible après redistribution qu''avant.', 1),
  ('da9c2610-20d0-5692-bc03-8f78c8ea5f25', '7e0ef681-b56b-55b9-b7ee-d2e5c34d4e13', 'Tailles, statuts, figures de l’entrepreneur', E'Une entreprise combine des facteurs de production pour vendre des biens ou des services. Sous ce mot unique, des réalités très différentes.\n\n## Une diversité de tailles\n| La catégorie | Le seuil | Son poids |\n| **Microentreprises** | Moins de 10 salariés | De très loin les plus **nombreuses** |\n| **PME** et **ETI** | Le tissu intermédiaire | Ossature de l''emploi local |\n| **Grandes entreprises** | Peu nombreuses | Concentrent l''emploi salarié, le chiffre d''affaires et l''export |\n\n## Une diversité de statuts\n| Le statut | Ce qui le caractérise |\n| **Entreprise individuelle** | Le patrimoine de l''entrepreneur est engagé ; régime simplifié du micro-entrepreneur |\n| **Sociétés** (SARL, SAS, SA) | Le patrimoine de l''entreprise est séparé de celui des propriétaires |\n| **Économie sociale et solidaire** | Coopératives, mutuelles, associations : le profit n''est pas la finalité, souvent « une personne, une voix » |\n| **Entreprises publiques** | Détenues majoritairement par l''État |\n\n## Les figures de l''entrepreneur\n| L''auteur | Ce qui définit l''entrepreneur |\n| **Schumpeter** | Celui qui **innove** — produit, procédé, débouché ou organisation nouvelle — et déclenche la « destruction créatrice » |\n| **Knight** | Celui qui assume l''**incertitude** : le risque non calculable, non assurable |\n| La **sociologie** | Origine sociale, capital économique et réseau pèsent sur la probabilité de créer et sur la survie |\n\n> Le statut de micro-entrepreneur, créé en 2008, a fait bondir le nombre de créations d''entreprises — sans transformer autant le tissu productif, ces entreprises étant très petites et souvent sans salarié.', 1),
  ('4cc9ac63-eaf0-5bc9-84e2-3d37ff1a3aef', 'a9a202ae-34d6-59e7-9fee-b9d20cfdb17c', 'Hiérarchie, coopération, conflits et gouvernance', E'Une entreprise n''est pas seulement un lieu de production : c''est une organisation traversée par le pouvoir, la coopération et le conflit.\n\n## L''organisation du travail\n| Le modèle | Ses principes | Sa limite |\n| **Taylorisme** | Division verticale (concevoir / exécuter) et horizontale, chronométrage, salaire au rendement | Monotonie, absentéisme |\n| **Fordisme** | La chaîne, la standardisation, les hauts salaires qui écoulent la production | Rigidité de la production de masse |\n| **Toyotisme** | Flux tendus, qualité totale, polyvalence, autonomie d''équipe | Intensification du travail |\n| **Ère numérique** | Travail en projet, télétravail, plateformes | Externalisation de la relation de travail |\n\n## Coopération et conflits\nLa coordination passe par la **hiérarchie**, mais aussi par des règles, des routines et une culture d''entreprise.\n\n> Crozier a montré que chaque acteur dispose d''une **zone d''incertitude** — une marge que sa position lui donne — et qu''il s''en sert comme d''une ressource de pouvoir, y compris à un échelon subalterne.\n\nLes **conflits** ne sont pas une pathologie : ils portent sur les salaires, les conditions de travail, l''emploi, la reconnaissance.\n\n| Forme en recul | Forme en hausse |\n| Grèves longues et massives dans le privé | Formes individuelles : absentéisme, turnover, recours prud''homal |\n| | Mobilisations courtes et médiatisées |\n\n## La gouvernance\nElle désigne la manière dont le pouvoir se distribue entre **actionnaires**, **dirigeants** et **parties prenantes** : salariés, clients, fournisseurs, territoire.\n\nLe problème central est la **relation d''agence** : le dirigeant (l''agent) ne poursuit pas nécessairement l''intérêt de l''actionnaire (le principal), et il en sait plus que lui.\n\n| Le mécanisme de contrôle | Ce qu''il vise |\n| Conseil d''administration | Surveiller les décisions |\n| Audit | Vérifier l''information |\n| Rémunération en actions | Aligner les intérêts |\n\n> Depuis les années 1980, la gouvernance actionnariale a pris le pas dans les grandes sociétés cotées ; la loi PACTE de 2019 a réintroduit en France l''idée que l''entreprise doit considérer les enjeux sociaux et environnementaux de son activité.', 1)
ON CONFLICT DO NOTHING;

-- 3. Quiz ------------------------------------------------------------------
-- Double garde : ON CONFLICT (id) protège du rejeu, et le NOT EXISTS protège
-- la leçon d’un SECOND quiz venu d’ailleurs — le hub de leçon lit son quiz en
-- .maybeSingle(), deux quiz feraient lever « multiple rows » à de vrais élèves.
INSERT INTO public.quizzes (id, title, subject, grade_level, chapter, is_free, lesson_id)
SELECT v.id, v.title, v.subject, v.grade_level, v.chapter, true, l.id
  FROM (VALUES
    ('79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Quiz — Une institution, pas un lieu', 'SES', '1re', 'Qu’est-ce qu’un marché ?', '2e1bbe13-49f3-5dff-be7e-3ce00424c4a8'::uuid),
    ('23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Quiz — Offre, demande et prix d’équilibre', 'SES', '1re', 'Comment un marché concurrentiel fonctionne-t-il ?', '08fc696a-95d3-561c-81cc-f4506a06e1c6'::uuid),
    ('d7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Quiz — Monopole, oligopole et concurrence monopolistique', 'SES', '1re', 'Comment les marchés imparfaitement concurrentiels fonctionnent-ils ?', '1beebc22-485f-5484-8653-a82cd17b6365'::uuid),
    ('8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Quiz — Externalités, biens collectifs et asymétries d’information', 'SES', '1re', 'Quelles sont les principales défaillances du marché ?', '22b91e9f-60cb-530e-a219-841138b010a4'::uuid),
    ('b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Quiz — Besoin de financement, capacité de financement', 'SES', '1re', 'Comment les agents économiques se financent-ils ?', '06fc14d8-df5c-5a08-9c79-3b99dc268481'::uuid),
    ('50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Quiz — Le prix du temps et du risque', 'SES', '1re', 'Le taux d’intérêt, le risque et les marchés de capitaux', '905808c0-51a3-53d5-aa26-d97cdec70256'::uuid),
    ('de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Quiz — Les formes de la monnaie', 'SES', '1re', 'Qu’est-ce que la monnaie ?', 'e03398e2-2627-58bf-b6bf-fe84ad6cb8eb'::uuid),
    ('7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Quiz — Compter, échanger, conserver', 'SES', '1re', 'Les trois fonctions de la monnaie', '1116538a-1336-5773-a8a9-64ff60eb099b'::uuid),
    ('248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Quiz — Les crédits font les dépôts', 'SES', '1re', 'Comment la monnaie est-elle créée ?', '40fc73bf-8453-51aa-b3ca-fa36cf466d92'::uuid),
    ('ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Quiz — Devenir un être social', 'SES', '1re', 'Comment la socialisation de l’enfant s’effectue-t-elle ?', '7927e1b3-223f-5d36-9989-04f0abdcb5ba'::uuid),
    ('209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Quiz — Ce que l’enfance dépose, ce que la vie adulte remanie', 'SES', '1re', 'De la socialisation primaire à la socialisation secondaire', 'ecaed378-ef4e-536a-b307-15a279aa1bec'::uuid),
    ('a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Quiz — Le genre, le milieu social, et les exceptions', 'SES', '1re', 'Socialisation différentielle et trajectoires improbables', '3401b787-8415-5d59-ba6b-7fa1d1057f92'::uuid),
    ('1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Quiz — Groupe social, agrégat, catégorie statistique', 'SES', '1re', 'Comment les individus s’associent-ils pour constituer des groupes sociaux ?', 'c4f6a4ea-d239-57c1-871e-361de3a1e942'::uuid),
    ('e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Quiz — Celui auquel on appartient, celui auquel on aspire', 'SES', '1re', 'Groupes d’appartenance, groupes de référence et sociabilité', 'd6be81ab-7648-5ea4-b038-3b88c2ea5e50'::uuid),
    ('c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Quiz — La force des liens faibles', 'SES', '1re', 'Comment les réseaux sociaux fonctionnent-ils ?', 'df58fb60-f0e8-59c8-98c8-b7787ea946e2'::uuid),
    ('b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Quiz — Contrôle formel, contrôle informel', 'SES', '1re', 'Comment le contrôle social s’exerce-t-il aujourd’hui ?', 'e28fa6fd-9e5e-54b8-b863-db31937ae571'::uuid),
    ('8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Quiz — Anomie, étiquetage, carrière déviante', 'SES', '1re', 'Quels sont les processus sociaux qui conduisent à la déviance ?', 'a7ee48e3-d395-5620-9097-b4c5f7b15cbd'::uuid),
    ('3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Quiz — Statistiques policières, enquêtes de victimation, chiffre noir', 'SES', '1re', 'Comment mesurer le niveau de la délinquance ?', 'f1cf4c1d-e318-59f2-91b3-7b7cf03f78e8'::uuid),
    ('bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Quiz — Des salons aux sondages', 'SES', '1re', 'Comment se forme et s’exprime l’opinion publique ?', 'fd049100-60eb-5e56-bfee-1870fdcb1db5'::uuid),
    ('3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'Quiz — Variables lourdes, vote sur enjeux, abstention', 'SES', '1re', 'Voter : une affaire individuelle ou collective ?', '267044db-e4d5-5f16-84dd-20b7329e902d'::uuid),
    ('d5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Quiz — Risque, mutualisation, protection sociale', 'SES', '1re', 'Comment l’assurance et la protection sociale gèrent-elles les risques ?', 'af377643-2efe-5843-bc5d-f7fa6776d925'::uuid),
    ('cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Quiz — Tailles, statuts, figures de l’entrepreneur', 'SES', '1re', 'Une diversité d’entreprises et d’entrepreneurs', 'da9c2610-20d0-5692-bc03-8f78c8ea5f25'::uuid),
    ('0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Quiz — Hiérarchie, coopération, conflits et gouvernance', 'SES', '1re', 'Comment les entreprises sont-elles organisées et gouvernées ?', '4cc9ac63-eaf0-5bc9-84e2-3d37ff1a3aef'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('190a8e6e-ada0-598b-83c7-e92429071974'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Qu’est-ce qui sort de la rencontre entre l’offre et la demande sur un marché ?', 'mcq', '["Un prix et une quantité échangée","Un salaire et un profit","Un impôt et une subvention","Un contrat de travail"]'::jsonb, 0, 'Le prix et la quantité d’équilibre sont les deux résultats de la confrontation.', 1),
    ('4a72fd69-7ebe-56ea-91ba-d3c5da0cdf82'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Un marché a nécessairement une existence physique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le marché des changes ou celui des actions n’ont aucun lieu : ce sont des réseaux d’échanges.', 2),
    ('b4de907b-4fa8-556a-92c2-f88162b975a2'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Que sont les droits de propriété ?', 'mcq', '["Le droit d’user d’un bien, d’en tirer un revenu et de le céder","Le droit de travailler","Le droit de vote des actionnaires","Le droit de créer une entreprise"]'::jsonb, 0, 'Usus, fructus, abusus : sans eux, personne ne peut vendre ni acheter durablement.', 3),
    ('aca1c968-5328-5a9b-b9fa-c2ef062e14da'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Quels sont les coûts de transaction ?', 'mcq', '["Les coûts de recherche, de négociation et d’exécution d’un échange","Les coûts de production d’un bien","Les impôts payés sur un achat","Les frais bancaires uniquement"]'::jsonb, 0, 'Ce sont les coûts de l’échange lui-même, distincts des coûts de production.', 4),
    ('8384dbb4-c7d1-5ad0-b21b-20d0499ff1d3'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Le prix ne joue qu’un seul rôle sur un marché : rémunérer le vendeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il informe, il incite et il rationne — trois fonctions à la fois.', 5),
    ('9fa28410-10e4-5345-8f3a-d4a270ebd258'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Quel mode de coordination repose sur l’ordre plutôt que sur le prix ?', 'mcq', '["La hiérarchie","Le marché","La réciprocité","Le troc"]'::jsonb, 0, 'Dans une entreprise, on ne négocie pas le prix de chaque tâche : on obéit à une organisation.', 6),
    ('1baa9593-340e-5fc5-b7df-c8cf0d06061d'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'Pourquoi la monnaie facilite-t-elle l’échange marchand ?', 'mcq', '["Elle évite d’avoir à trouver un partenaire aux désirs exactement inverses","Elle fait baisser les prix","Elle supprime les coûts de transaction","Elle garantit la qualité des biens"]'::jsonb, 0, 'Le troc exige une double coïncidence des désirs, très coûteuse à obtenir.', 7),
    ('dabc70e8-63dc-5d03-be85-a9587e84d572'::uuid, '79c1f8ce-6b4c-50ce-8f20-1d12f4f9838c'::uuid, 'L’intervention de l’État est incompatible avec l’existence d’un marché.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le marché suppose au contraire un État qui définit les droits et fait respecter les contrats.', 8),
    ('3f628dee-cc5f-5d5c-a366-9369d2d4541c'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Combien de conditions définissent la concurrence parfaite ?', 'mcq', '["Cinq","Deux","Trois","Sept"]'::jsonb, 0, 'Atomicité, homogénéité, libre entrée et sortie, transparence, mobilité des facteurs.', 1),
    ('1a0012b0-bb99-548f-b06a-2baf3a42c56f'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Que se passe-t-il quand le prix est supérieur au prix d’équilibre ?', 'mcq', '["L’offre excède la demande et le prix tend à baisser","La demande excède l’offre et le prix tend à monter","Le marché disparaît","La quantité échangée augmente"]'::jsonb, 0, 'La mévente pousse les vendeurs à réviser leur prix à la baisse.', 2),
    ('bef2e929-3e78-58dc-a99b-d8c095332ed4'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Une hausse du revenu des ménages déplace la courbe de demande vers la droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce n’est pas le prix du bien qui change : c’est toute la courbe qui se décale.', 3),
    ('944aa51f-0a43-53ad-92eb-2d011cc7ec09'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Que signifie « être preneur de prix » ?', 'mcq', '["Subir le prix du marché sans pouvoir l’influencer","Fixer librement son prix de vente","Négocier le prix avec chaque client","Acheter au prix le plus bas possible"]'::jsonb, 0, 'C’est la conséquence de l’atomicité : chaque agent est trop petit pour peser.', 4),
    ('3dec9b86-ee90-58a9-879b-67854f06b246'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Le surplus du consommateur correspond à…', 'mcq', '["la différence entre ce qu’il était prêt à payer et ce qu’il a payé","la somme dépensée pour acheter le bien","le profit réalisé par le vendeur","la quantité qu’il n’a pas pu acheter"]'::jsonb, 0, 'C’est le gain que l’échange lui procure au prix d’équilibre.', 5),
    ('60e4c446-50a0-58d0-a537-d8c36faa153f'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Une baisse du coût de production déplace la courbe d’offre vers la droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À chaque prix, les producteurs acceptent d’offrir davantage : le prix d’équilibre baisse.', 6),
    ('9bf8a399-2189-5f96-885e-8ac89fc342e9'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'Pourquoi la courbe de demande est-elle décroissante ?', 'mcq', '["Parce qu’une hausse du prix décourage une partie des acheteurs","Parce que les producteurs offrent moins","Parce que les revenus baissent","Parce que la qualité diminue"]'::jsonb, 0, 'À prix plus élevé, certains renoncent ou se tournent vers un substitut.', 7),
    ('2f7a98df-6245-50a1-8e6e-00869eb70cf1'::uuid, '23845667-1b6f-5852-bfe2-0c140abbca80'::uuid, 'En concurrence parfaite, un producteur peut vendre plus cher que ses concurrents sans perdre de clients.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le produit étant homogène et l’information parfaite, il perdrait toute sa clientèle.', 8),
    ('ffcf7074-5c4e-5685-ba70-45c6cfa9e845'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Qu’est-ce qu’un « faiseur de prix » ?', 'mcq', '["Un producteur qui dispose d’un pouvoir de marché et fixe son prix","Un consommateur qui négocie","Un producteur qui subit le prix du marché","L’État quand il fixe un prix administré"]'::jsonb, 0, 'C’est l’inverse du price taker de la concurrence parfaite.', 1),
    ('a2e346b6-47db-5879-bbb9-d45cc6873733'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Qu’est-ce qu’un monopole naturel ?', 'mcq', '["Un marché où une seule entreprise produit à un coût plus bas que plusieurs","Un monopole créé par la loi","Un monopole issu d’une entente","Un monopole temporaire dû à un brevet"]'::jsonb, 0, 'Les coûts fixes très élevés d’un réseau rendent la duplication absurde.', 2),
    ('0baab1f2-3326-5603-8aa3-08efd419ea43'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'En monopole, le prix est plus élevé et la quantité échangée plus faible qu’en concurrence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le monopoleur restreint la quantité pour vendre plus cher.', 3),
    ('0e43135c-84fa-5590-b307-19423fe685d3'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Qu’est-ce qui caractérise l’oligopole ?', 'mcq', '["L’interdépendance stratégique entre quelques offreurs","L’absence totale de concurrence","L’homogénéité parfaite des produits","La libre entrée sur le marché"]'::jsonb, 0, 'Chaque décision dépend de l’anticipation du comportement des rivaux.', 4),
    ('9d0552a3-9952-52a0-8296-cf168213535d'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Une entente entre concurrents sur les prix est autorisée si elle est publique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le cartel est interdit et lourdement sanctionné : il reconstitue un monopole.', 5),
    ('1bf74e0f-3a82-5824-8dc4-90940be72117'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Sur quoi repose la concurrence monopolistique ?', 'mcq', '["La différenciation des produits","Le nombre réduit d’offreurs","L’existence d’un brevet unique","L’intervention de l’État"]'::jsonb, 0, 'Chaque producteur détient un mini-monopole sur sa variété.', 6),
    ('9e9282d1-cf1a-5cf5-a05e-5956ddef79a4'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'Qu’est-ce qu’une barrière à l’entrée ?', 'mcq', '["Un obstacle qui dissuade de nouveaux concurrents d’entrer sur le marché","Une taxe sur les importations","Un plafond de prix imposé par l’État","Une limite au nombre de clients"]'::jsonb, 0, 'Coûts fixes, brevets, réputation, réseaux de distribution en sont des exemples.', 7),
    ('d4668e51-41be-56ca-acf5-46e008dfaf74'::uuid, 'd7baf262-d5b8-58b6-8af6-ae1917c1b3e6'::uuid, 'La politique de la concurrence interdit à une entreprise d’être grande.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle sanctionne l’abus de position dominante, pas la position dominante elle-même.', 8),
    ('1e2542eb-03ec-5115-8817-85adf55085ee'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Qu’est-ce qu’une externalité négative ?', 'mcq', '["Un effet dommageable subi par un tiers sans compensation","Une perte subie par le producteur","Une taxe sur la production","Un défaut de qualité du produit"]'::jsonb, 0, 'La pollution en est l’exemple type : son coût n’entre pas dans le prix.', 1),
    ('192226d3-13b7-5e64-83b9-c3cfb8c20b08'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'En présence d’une externalité négative, le marché produit une quantité trop faible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le coût social n’étant pas payé, le prix est trop bas et la quantité trop élevée.', 2),
    ('c2e3b2f8-9608-5aa4-a126-459dedd07f51'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Quelles sont les deux propriétés d’un bien collectif ?', 'mcq', '["Non-rivalité et non-excluabilité","Rareté et cherté","Rivalité et excluabilité","Gratuité et abondance"]'::jsonb, 0, 'L’éclairage public réunit les deux : chacun en profite sans priver personne.', 3),
    ('094d4b6e-d251-5c05-88b1-6fcc3cdee1a1'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Qu’est-ce que le comportement de passager clandestin ?', 'mcq', '["Profiter d’un bien collectif sans contribuer à son financement","Vendre un bien de mauvaise qualité","Acheter sans payer de TVA","Se retirer d’un marché non rentable"]'::jsonb, 0, 'C’est pourquoi le financement passe par l’impôt et non par le prix.', 4),
    ('5a4d0d25-94e8-58cb-b635-46204852b035'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'La sélection adverse intervient avant la signature du contrat.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle porte sur une qualité cachée ; l’aléa moral, lui, porte sur un comportement postérieur.', 5),
    ('4588e236-fcb5-5b88-803c-5922b50a5667'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Que montre Akerlof avec le marché des voitures d’occasion ?', 'mcq', '["Que l’asymétrie d’information peut faire disparaître les biens de qualité","Que les prix finissent toujours par s’équilibrer","Que la publicité augmente les prix","Que le monopole est inévitable"]'::jsonb, 0, 'Les bons vendeurs se retirent d’un marché qui ne paie qu’un prix moyen.', 6),
    ('51dc35f5-a02a-58ab-901d-caef6a26a112'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Quel remède applique le principe pollueur-payeur ?', 'mcq', '["La taxe sur les activités polluantes","La subvention à la recherche","La gratuité du service","Le brevet"]'::jsonb, 0, 'Elle réintègre dans le prix le coût supporté par la collectivité.', 7),
    ('834e1cc4-14a1-5092-a7a8-570b2fa0d371'::uuid, '8ad95439-bc9c-5bc4-9e31-2587698721ba'::uuid, 'Une franchise d’assurance sert à limiter l’aléa moral.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En laissant une part du dommage à la charge de l’assuré, elle le maintient prudent.', 8),
    ('7a686187-691b-5c51-8677-c91332feddd0'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Quand un agent a-t-il un besoin de financement ?', 'mcq', '["Quand son investissement dépasse son épargne","Quand son épargne dépasse son investissement","Quand son revenu baisse","Quand il rembourse un emprunt"]'::jsonb, 0, 'Il doit alors trouver des fonds auprès des agents à capacité de financement.', 1),
    ('2f4c2618-b8a4-5609-9bda-af318f783d21'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Dans l’ensemble, les ménages français dégagent une capacité de financement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Leur épargne excède leurs investissements, essentiellement immobiliers.', 2),
    ('1529ecff-31a3-5abe-a470-9be479b2a292'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Qu’est-ce que l’autofinancement ?', 'mcq', '["Le financement d’un investissement par ses propres ressources","Un prêt bancaire à taux zéro","L’émission d’obligations","Une subvention publique"]'::jsonb, 0, 'Il mobilise les bénéfices mis en réserve, sans coût d’intérêt.', 3),
    ('6c43452f-6ee1-52cc-88ea-aaef439a0e6e'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Une action est un titre de créance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un titre de PROPRIÉTÉ ; l’obligation, elle, est un titre de créance.', 4),
    ('bb7f85a6-a131-5cbd-98ac-5df1e65530e1'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Qu’est-ce que le financement externe indirect ?', 'mcq', '["Un financement passant par un intermédiaire bancaire","Une émission d’actions en Bourse","L’usage des bénéfices non distribués","Un don entre entreprises"]'::jsonb, 0, 'La banque s’interpose entre l’épargnant et l’emprunteur.', 5),
    ('572c32d3-6b0b-5947-bb9d-609dc4e54887'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Que perçoit le détenteur d’une obligation ?', 'mcq', '["Un intérêt, puis le remboursement du capital","Un dividende variable","Une part du capital de l’entreprise","Un droit de vote en assemblée générale"]'::jsonb, 0, 'C’est un prêt : rémunération fixée à l’avance et remboursement à l’échéance.', 6),
    ('70bb0cd0-dd69-512e-90f5-d4f0ec5e3ba4'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Émettre des actions dilue le contrôle des propriétaires existants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De nouveaux actionnaires entrent au capital et votent en assemblée générale.', 7),
    ('3de70510-78da-5c34-a80b-d5b153d5f5ac'::uuid, 'b8e857a1-2f1a-5e39-962b-12546db1ae5f'::uuid, 'Quelle est la fonction principale du système financier ?', 'mcq', '["Transférer les fonds des agents à capacité vers ceux à besoin de financement","Fixer le niveau des prix","Collecter l’impôt","Produire des biens et services marchands"]'::jsonb, 0, 'Sans ce transfert, l’épargne des uns ne financerait pas l’investissement des autres.', 8),
    ('6b828942-92c5-548b-840f-c6e88e4d946b'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Que rémunère le taux d’intérêt ?', 'mcq', '["Le renoncement à une somme d’argent pendant une durée","Le travail du banquier","La qualité du bien financé","Le montant de l’impôt payé"]'::jsonb, 0, 'C’est le prix du temps, majoré d’une prime de risque.', 1),
    ('fbe41ff1-e853-5cea-a98e-fd3b990d20ee'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Un emprunteur risqué obtient un taux d’intérêt plus bas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il paie au contraire une prime de risque : le taux est plus élevé.', 2),
    ('ffa7418d-1284-585e-926d-11f9e7dda1e4'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Comment calcule-t-on approximativement le taux d’intérêt réel ?', 'mcq', '["Taux nominal moins taux d’inflation","Taux nominal plus taux d’inflation","Taux nominal divisé par la durée","Taux directeur moins prime de risque"]'::jsonb, 0, 'C’est le pouvoir d’achat réellement gagné ou perdu.', 3),
    ('aafb0875-a282-52aa-aebd-ddf9abffa9c7'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Une inflation plus forte que le taux nominal avantage l’emprunteur à taux fixe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le taux réel devient négatif : il rembourse en monnaie dépréciée.', 4),
    ('cf5adedd-b875-5716-b60a-5e78e775dc05'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Que se passe-t-il sur le marché primaire ?', 'mcq', '["Les titres sont émis et l’émetteur lève des fonds","Les titres sont revendus entre investisseurs","Les banques se refinancent auprès de la banque centrale","Les devises sont échangées"]'::jsonb, 0, 'C’est le seul moment où l’argent va réellement à l’émetteur.', 5),
    ('8b58c0ce-2603-5c92-b0ec-152261059366'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'À quoi sert le marché secondaire ?', 'mcq', '["À rendre les titres liquides en permettant leur revente","À financer directement les entreprises","À fixer les taux directeurs","À collecter l’épargne des ménages"]'::jsonb, 0, 'Sans liquidité, personne n’accepterait de souscrire à l’émission.', 6),
    ('4e5b3abb-085c-5017-9955-45203cb75444'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Qu’appelle-t-on transformation bancaire ?', 'mcq', '["Financer des prêts longs avec des ressources courtes","Changer des euros en devises","Transformer une action en obligation","Fusionner deux banques"]'::jsonb, 0, 'C’est ce qui rend la banque utile — et vulnérable en cas de retraits massifs.', 7),
    ('50575bbb-05b1-50a6-8c44-216cb6fcde30'::uuid, '50a20337-5ee3-5ed6-84dc-5e3a813aff9e'::uuid, 'Le taux directeur de la banque centrale influence l’ensemble des taux de l’économie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il fixe le coût auquel les banques se refinancent, qu’elles répercutent sur leurs clients.', 8),
    ('49de228b-9a51-5c7e-80be-39b08783320e'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Quelle forme de monnaie représente aujourd’hui l’essentiel de la masse monétaire ?', 'mcq', '["La monnaie scripturale","La monnaie fiduciaire","La monnaie marchandise","Les cryptomonnaies"]'::jsonb, 0, 'Ce sont les soldes des comptes bancaires, de simples écritures.', 1),
    ('c9c9fb51-56d1-5010-aaa2-0de74d92e60f'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'La carte bancaire est une forme de monnaie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un instrument de circulation de la monnaie scripturale, pas la monnaie elle-même.', 2),
    ('aba3e096-a4c6-5876-8826-ec3c70d343c2'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'D’où vient le mot « fiduciaire » ?', 'mcq', '["Du latin fiducia, la confiance","Du grec fides, la valeur","Du nom d’un banquier florentin","Du latin fiscus, le trésor"]'::jsonb, 0, 'Le billet ne vaut que par la confiance qu’on lui accorde.', 3),
    ('f4cd843b-891f-5cda-9a0a-1d04b6cc0c68'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Qu’est-ce que la confiance méthodique dans la monnaie ?', 'mcq', '["Chacun l’accepte parce qu’il sait que les autres l’accepteront","L’État garantit son cours légal","Elle repose sur une réserve d’or","Les banques la contrôlent"]'::jsonb, 0, 'C’est une croyance auto-réalisatrice, le premier pilier de la confiance.', 4),
    ('84c73ce5-d3b4-532b-92ea-10a942f508b3'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'La valeur d’un billet de banque vient de la valeur du papier qui le compose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle vient de la confiance et du cours légal, jamais du support.', 5),
    ('0c419a64-e860-55ef-b5d6-da784d2ef395'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Qu’était la monnaie marchandise ?', 'mcq', '["Un bien qui valait par sa matière propre","Une écriture comptable","Un billet garanti par l’État","Une créance sur une banque"]'::jsonb, 0, 'Sel, bétail, métaux précieux : la valeur tenait au bien lui-même.', 6),
    ('cf504440-6b71-501a-9ca0-472099e41f26'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Pourquoi les cryptomonnaies remplissent-elles mal la fonction de réserve de valeur ?', 'mcq', '["Parce que leur cours est très volatil","Parce qu’elles sont interdites","Parce qu’elles sont matérielles","Parce qu’elles ne circulent pas"]'::jsonb, 0, 'Une réserve de valeur suppose une valeur stable dans le temps.', 7),
    ('fed46ebf-f80f-515a-a5af-156ef7f81454'::uuid, 'de0dca93-77c0-5a3c-8659-2a2b948b296f'::uuid, 'Une hyperinflation traduit un effondrement de la confiance dans la monnaie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’Allemagne de 1923 en est l’exemple classique.', 8),
    ('162f028e-d149-5e96-b66e-410d3ebed31b'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Quelles sont les trois fonctions de la monnaie ?', 'mcq', '["Unité de compte, intermédiaire des échanges, réserve de valeur","Épargne, investissement, consommation","Émission, circulation, destruction","Prêt, dépôt, placement"]'::jsonb, 0, 'Elles sont identifiées depuis Aristote et restent au programme.', 1),
    ('86a30eac-8e82-5db0-9624-63cb43eb104e'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Quelle fonction de la monnaie l’inflation dégrade-t-elle le plus ?', 'mcq', '["La réserve de valeur","L’unité de compte","L’intermédiaire des échanges","Aucune"]'::jsonb, 0, 'Le pouvoir d’achat conservé fond avec la hausse des prix.', 2),
    ('c8dc6c06-9446-55c0-9a4b-3057d2fab446'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Le troc suppose une double coïncidence des désirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chacun doit vouloir exactement ce que l’autre possède : c’est très coûteux.', 3),
    ('3fbaa8bc-dfab-5c99-b379-ecd6387c5cfa'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Que contient l’agrégat M1 ?', 'mcq', '["Les pièces, les billets et les dépôts à vue","Les livrets d’épargne uniquement","Les actions et obligations","Les crédits accordés par les banques"]'::jsonb, 0, 'C’est la monnaie immédiatement disponible pour payer.', 4),
    ('cea42e13-6da9-55aa-85f3-39a297092eeb'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'L’unité de compte réduit le nombre de prix à connaître dans une économie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle remplace des milliers de prix relatifs par un prix par bien.', 5),
    ('6fb549aa-ba47-54bb-8d9d-0173207eb30d'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Que permet la fonction d’intermédiaire des échanges ?', 'mcq', '["De séparer l’acte de vente de l’acte d’achat","De mesurer la valeur des biens","De conserver du pouvoir d’achat","De calculer l’inflation"]'::jsonb, 0, 'On vend d’abord, on achète ensuite, à un autre partenaire.', 6),
    ('910371af-14f6-56e2-96c3-4b9cde71398f'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Les agrégats monétaires sont classés par liquidité décroissante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De M1, la plus liquide, à M3, qui l’englobe et contient des placements moins disponibles.', 7),
    ('0a2bee10-0a46-5b36-bce7-8708fac198d0'::uuid, '7a4d2e20-9d7c-57c6-94b7-3768505556a3'::uuid, 'Qu’appelle-t-on préférence pour la liquidité chez Keynes ?', 'mcq', '["Le désir de conserver de la monnaie plutôt que de la placer","La préférence pour les biens durables","Le choix du crédit plutôt que de l’épargne","Le refus des billets au profit des pièces"]'::jsonb, 0, 'Elle repose sur des motifs de transaction, de précaution et de spéculation.', 8),
    ('d8fb460c-81c5-567e-924d-329e86fa45c2'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Qui crée l’essentiel de la monnaie en circulation ?', 'mcq', '["Les banques commerciales, en accordant des crédits","La banque centrale, en imprimant des billets","L’État, par l’impôt","Les entreprises, en émettant des actions"]'::jsonb, 0, 'La monnaie scripturale naît de l’écriture qui accompagne le crédit.', 1),
    ('4f3ab95d-697b-5083-9058-9a6077c3dabe'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Le remboursement d’un crédit détruit de la monnaie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’écriture s’annule : la création dure le temps du prêt.', 2),
    ('f1d1ab99-f184-51ec-bcbf-1885f89cd67d'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Que signifie « les crédits font les dépôts » ?', 'mcq', '["Le crédit crée le dépôt, et non l’inverse","Les dépôts des clients financent les crédits","Les banques prêtent l’épargne collectée","La banque centrale finance chaque prêt"]'::jsonb, 0, 'La banque n’a pas besoin d’un dépôt préalable pour prêter.', 3),
    ('6e88a0d4-9064-58a6-960a-7d223953b270'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Qu’est-ce que la monnaie centrale ?', 'mcq', '["La monnaie qui circule entre les banques et la banque centrale","Les pièces et billets détenus par les ménages","Le solde des comptes courants","L’épargne réglementée"]'::jsonb, 0, 'Elle sert aux règlements interbancaires et couvre les fuites.', 4),
    ('bcd7e4f5-163d-504b-90d0-6fc9c189c556'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Quel est l’objectif principal de la Banque centrale européenne ?', 'mcq', '["La stabilité des prix","Le plein emploi","L’équilibre du budget de l’État","La croissance du PIB"]'::jsonb, 0, 'Une inflation proche de 2 % à moyen terme, inscrite dans les traités.', 5),
    ('87554eed-e997-54d1-a990-624678a96613'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Les banques peuvent créer de la monnaie sans aucune limite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Fuites, réserves obligatoires, ratios prudentiels et demande de crédit les bornent.', 6),
    ('f79681db-cd4b-5745-bdc0-4a6ca5222e39'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'Qu’est-ce que le taux directeur ?', 'mcq', '["Le taux auquel les banques se refinancent auprès de la banque centrale","Le taux moyen des crédits immobiliers","Le taux d’inflation cible","Le taux de rendement des obligations d’État"]'::jsonb, 0, 'Il se répercute sur tous les taux de l’économie.', 7),
    ('df4717ce-6e12-5bc4-a1d4-13662bab79b1'::uuid, '248d664c-4c36-5454-ba3c-469231aa7c8a'::uuid, 'L’achat massif de titres par la banque centrale augmente la quantité de monnaie centrale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle règle ces achats en créant de la monnaie centrale.', 8),
    ('2dab9a92-cb97-55dd-9e5a-f96bfcb9c830'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Qu’est-ce que la socialisation ?', 'mcq', '["L’apprentissage et l’intériorisation des normes et valeurs d’une société","Le fait de se faire des amis","L’inscription à une association","L’adaptation au marché du travail"]'::jsonb, 0, 'C’est le processus qui fait de l’individu un être social.', 1),
    ('97a89105-fcf8-5732-b8ef-965fbff3b135'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Quelle est la différence entre une valeur et une norme ?', 'mcq', '["La valeur est un idéal, la norme la règle concrète qui la traduit","La valeur est juridique, la norme morale","La norme est un idéal, la valeur une règle","Il n’y en a aucune"]'::jsonb, 0, 'L’égalité est une valeur ; la file d’attente, une norme qui la traduit.', 2),
    ('786019c2-02ef-5c3a-a7c9-1ee395373942'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'La famille est la première instance de socialisation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est la plus précoce et la plus durable, ce qui lui donne un poids particulier.', 3),
    ('ede209f6-2bf5-58e4-852b-18aa5be0ac99'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Qu’est-ce que l’habitus chez Bourdieu ?', 'mcq', '["Un ensemble de dispositions durables incorporées par la socialisation","Une habitude passagère","Le statut juridique d’un individu","Un rôle professionnel"]'::jsonb, 0, 'Il oriente goûts et conduites sans passer par le calcul conscient.', 4),
    ('421526c1-b3db-5817-b253-166f79ff9666'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'L’enfant est passif dans le processus de socialisation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il négocie, résiste et réinterprète ce qui lui est transmis.', 5),
    ('773d11cf-46c9-57ea-8a66-d2ed08cbbe4e'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Qu’est-ce qu’un rôle social ?', 'mcq', '["Le comportement attendu de celui qui occupe une position sociale","Un métier salarié","Une valeur partagée","Une sanction pénale"]'::jsonb, 0, 'Le rôle est la face vécue du statut.', 6),
    ('36f28a5b-ceb7-5742-bc43-9df8bac34935'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'Quelle instance devient particulièrement influente à l’adolescence ?', 'mcq', '["Le groupe de pairs","La famille","L’entreprise","Le syndicat"]'::jsonb, 0, 'Ses codes entrent parfois en concurrence avec ceux de la famille.', 7),
    ('deceeac0-09af-5218-9806-fe24f42d89f2'::uuid, 'ec576427-abc1-56fb-bbb6-ac03ff464747'::uuid, 'La socialisation transmet les mêmes contenus quel que soit le milieu social.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est différenciée selon le milieu et le genre : c’est ce qui explique les écarts de comportement.', 8),
    ('7db39d00-fd03-5c09-81c1-fe5e46b33c95'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Quels sont les trois traits de la socialisation primaire ?', 'mcq', '["Globale, affective et durable","Courte, choisie et spécialisée","Professionnelle, volontaire et réversible","Scolaire, obligatoire et publique"]'::jsonb, 0, 'C’est ce qui lui donne son empreinte particulière.', 1),
    ('e6122862-c84c-53cf-9d7a-de88dbc19abf'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'La socialisation secondaire est plus spécialisée que la primaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle porte sur un univers particulier : le travail, le couple, une association.', 2),
    ('ba871417-0b59-50c1-a613-1369bf020839'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Qu’est-ce que la socialisation anticipatrice ?', 'mcq', '["L’adoption des normes d’un groupe qu’on espère rejoindre","La socialisation avant la naissance","La socialisation par les parents uniquement","L’apprentissage accéléré d’un métier"]'::jsonb, 0, 'Merton l’a mise en évidence : elle prépare et facilite la mobilité.', 3),
    ('89d452d4-a92b-5179-94a1-b192d5047a69'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Qui a proposé la notion d’alternation ?', 'mcq', '["Berger et Luckmann","Bourdieu et Passeron","Durkheim","Merton"]'::jsonb, 0, 'Elle désigne une resocialisation qui rompt avec la socialisation primaire.', 4),
    ('6902695d-f408-59d7-b262-5baffe829419'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'La socialisation secondaire efface systématiquement la socialisation primaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle s’y superpose ; les deux peuvent entrer en conflit durablement.', 5),
    ('0b8956ef-f273-5a34-84f5-31b764467dfb'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Dans la socialisation secondaire, l’individu est…', 'mcq', '["plus actif dans le choix des groupes qui le socialisent","entièrement passif","soumis aux mêmes liens affectifs que dans l’enfance","coupé de toute instance"]'::jsonb, 0, 'On choisit son métier, son couple, son association — pas sa famille d’origine.', 6),
    ('4bf8dcf3-13f5-5940-a0e9-dec1135743fc'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Une trajectoire de mobilité sociale ascendante peut créer une tension entre les deux socialisations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les dispositions incorporées dans l’enfance se heurtent aux codes du nouveau milieu.', 7),
    ('f887a077-7578-5d14-8537-0301b97d887f'::uuid, '209e5247-531e-5803-9457-2ac8149a5bd8'::uuid, 'Pourquoi la socialisation primaire est-elle si durable ?', 'mcq', '["Parce qu’elle est apprise très tôt et vécue comme allant de soi","Parce qu’elle est écrite dans la loi","Parce qu’elle est répétée à l’âge adulte","Parce qu’elle est volontaire"]'::jsonb, 0, 'Elle s’incorpore sans être perçue comme un apprentissage.', 8),
    ('3440c2f9-33c9-58e0-90f0-101720e3464a'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Qu’est-ce que la socialisation genrée ?', 'mcq', '["La transmission de normes et de rôles différents selon le sexe","L’apprentissage de la biologie à l’école","Le choix d’un métier par les parents","La séparation des classes filles et garçons"]'::jsonb, 0, 'Elle commence dès la naissance et produit des dispositions durables.', 1),
    ('e6c44f24-8cac-5e1a-b393-571041a47524'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Les écarts d’orientation scolaire entre filles et garçons s’expliquent d’abord par des différences d’aptitudes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les filles réussissent mieux à l’école : c’est la socialisation, non l’aptitude, qui pèse.', 2),
    ('d7216431-15d2-541f-ab98-41248ef37f32'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Qu’est-ce que le capital culturel chez Bourdieu ?', 'mcq', '["L’ensemble des ressources culturelles héritées et incorporées","Le budget culturel d’un ménage","Le nombre de diplômes obtenus par un individu","La subvention publique à la culture"]'::jsonb, 0, 'L’école le récompense sans l’avoir transmis, ce qui avantage certains milieux.', 3),
    ('33e0c0a8-44e1-564e-a3bb-848135e35557'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Une trajectoire improbable prouve que la socialisation n’a aucun effet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle rappelle seulement que la socialisation produit des probabilités, pas des destins.', 4),
    ('c99c5c1e-7740-5996-b6bd-01823e52fd81'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Quel élément revient souvent dans les trajectoires improbables ?', 'mcq', '["Un fort investissement scolaire de la famille ou une rencontre décisive","Un héritage financier important","Un déménagement à l’étranger","Un changement de nom"]'::jsonb, 0, 'La configuration familiale et les rencontres jouent un rôle documenté.', 5),
    ('2b756b89-32ed-50dd-bd31-efc3828e0226'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Le rapport au langage transmis dans la famille varie selon le milieu social.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et l’école valorise le registre le plus proche de celui des milieux favorisés.', 6),
    ('b8bcf85a-138e-58e5-a892-bcb870bc0a7a'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Que signifie « déterminisme statistique » en sociologie ?', 'mcq', '["Une position sociale rend certains comportements plus probables sans les imposer","Chaque individu est entièrement déterminé","Les statistiques prédisent l’avenir individuel","Les comportements sont totalement libres"]'::jsonb, 0, 'C’est la distinction entre probabilité collective et destin individuel.', 7),
    ('dbe7ab64-4eb5-5cd1-932a-f4852af7974d'::uuid, 'a4bc5b15-1793-511f-bb45-f5513d0ee2b3'::uuid, 'Décrire un même comportement d’enfant comme « vive » ou « turbulent » selon le sexe relève de la socialisation genrée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le vocabulaire employé oriente l’estime de soi et les conduites attendues.', 8),
    ('d4cef23e-fef9-5e80-9c42-75bb328cfe61'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Quelles sont les trois conditions d’un groupe social ?', 'mcq', '["Des interactions, un sentiment d’appartenance et une reconnaissance extérieure","Un lieu, une heure et un but commun","Un statut juridique, un budget et un président","Un âge, un sexe et une profession communs"]'::jsonb, 0, 'Sans interactions ni conscience d’appartenance, il n’y a pas de groupe.', 1),
    ('2ca34174-3015-501a-94f7-c4f86fd85670'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Les voyageurs d’un même wagon forment un groupe social.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un agrégat physique : proximité sans interaction ni appartenance.', 2),
    ('835012c4-d5b4-595d-9b9b-a5f206a11adf'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Qu’est-ce qu’une catégorie statistique ?', 'mcq', '["Un ensemble d’individus partageant un caractère mesurable sans se connaître","Un groupe organisé autour d’un objectif","Une classe sociale mobilisée","Une association déclarée"]'::jsonb, 0, 'Les 15-24 ans en sont une : ils ne forment pas un groupe pour autant.', 3),
    ('401d4a3a-7a13-55d9-9722-6a3d0ff5cb62'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Qui distingue groupes primaires et groupes secondaires ?', 'mcq', '["Cooley","Durkheim","Weber","Granovetter"]'::jsonb, 0, 'Le primaire est restreint et affectif, le secondaire vaste et fonctionnel.', 4),
    ('17001075-5f9b-51f1-825b-c6c212e4a13f'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Un groupe informel n’existe pas dans une entreprise dotée d’un organigramme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les deux coexistent : les affinités doublent toujours la structure officielle.', 5),
    ('f2b0ad1d-ae42-57a9-b4dc-faa4616559f7'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Qu’est-ce que l’homophilie ?', 'mcq', '["La tendance à s’associer à ceux qui nous ressemblent","L’attrait pour la nouveauté","Le rejet des groupes extérieurs","La préférence pour les groupes nombreux"]'::jsonb, 0, 'Elle explique une grande part de la composition des réseaux personnels.', 6),
    ('d90a458e-eca9-5fcb-8613-18ea00e09084'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Le passage de la classe en soi à la classe pour soi décrit…', 'mcq', '["la prise de conscience collective qui transforme une catégorie en groupe","la montée dans la hiérarchie sociale","la disparition des classes sociales","le changement de catégorie professionnelle"]'::jsonb, 0, 'C’est l’analyse marxiste de la mobilisation.', 7),
    ('d75ad785-9f7f-51e3-88c0-d4c34507fa0e'::uuid, '1bce7212-58fa-58ce-8ab9-46beaa5af710'::uuid, 'Une famille est un groupe primaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Relations directes, durables et affectives : la définition même du groupe primaire.', 8),
    ('a6d2f50f-ae9a-59f9-a65e-a63bdb023ef8'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Qu’est-ce qu’un groupe de référence ?', 'mcq', '["Un groupe dont on adopte les normes, qu’on en fasse partie ou non","Le groupe où l’on est né","Le groupe le plus nombreux d’une société","Un groupe reconnu par la loi"]'::jsonb, 0, 'Merton l’a distingué du groupe d’appartenance.', 1),
    ('a23a3fff-82ac-5253-bf60-9371c0d9b933'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Un individu adopte toujours les normes de son groupe d’appartenance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il peut se référer à un autre groupe — c’est la socialisation anticipatrice.', 2),
    ('797eaa35-41bd-537f-b01c-9a411087ae79'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Quel lien social correspond à la division du travail ?', 'mcq', '["Le lien de participation organique","Le lien de filiation","Le lien de participation élective","Le lien de citoyenneté"]'::jsonb, 0, 'Il naît de l’interdépendance entre les fonctions productives.', 3),
    ('6f0f6408-269a-51e0-8b7d-4baabc2d15d3'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Les liens sociaux contemporains sont plus électifs et plus réversibles qu’autrefois.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On les choisit davantage, et ils se défont plus facilement.', 4),
    ('2aaa1fbd-aab8-5437-a3ab-8e486324fb62'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Comment varie la sociabilité selon le milieu social ?', 'mcq', '["Elle est plus étendue et plus associative dans les milieux favorisés","Elle est identique dans tous les milieux","Elle est plus forte dans les milieux populaires uniquement","Elle ne dépend que de l’âge"]'::jsonb, 0, 'Le milieu change à la fois l’intensité et la forme des relations.', 5),
    ('e7110676-5d8a-56bd-a429-a5019269eaee'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Quel lien social relève de la filiation ?', 'mcq', '["Le lien familial et intergénérationnel","Le lien professionnel","Le lien associatif","Le lien politique"]'::jsonb, 0, 'C’est le premier lien, hérité et non choisi.', 6),
    ('f4e4b58c-2710-5c55-98d8-523d8ffe2887'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'La perte d’emploi fragilise le lien social au-delà de la perte de revenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le travail est aussi un lieu de sociabilité et de reconnaissance.', 7),
    ('398a0fd8-1e42-59da-a695-ea17acda1da5'::uuid, 'e6603d82-a493-50e3-af1d-979bbba813f3'::uuid, 'Que désigne la sociabilité en sociologie ?', 'mcq', '["L’ensemble des relations qu’un individu entretient effectivement","Le caractère aimable d’une personne","Le nombre d’associations d’un territoire","La politesse apprise dans la famille"]'::jsonb, 0, 'Elle se mesure par les contacts, leur fréquence et leur nature.', 8),
    ('841e6ebd-3b81-5ffb-9e9c-f17631acd996'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Qui a mis en évidence la force des liens faibles ?', 'mcq', '["Mark Granovetter","Robert Merton","Émile Durkheim","Charles Cooley"]'::jsonb, 0, 'Son article de 1973 est devenu un classique de la sociologie des réseaux.', 1),
    ('721ac2b9-56b2-5cc9-bc37-4d78d2e1c992'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Pourquoi les liens faibles sont-ils précieux pour trouver un emploi ?', 'mcq', '["Parce qu’ils apportent une information nouvelle, venue d’un autre milieu","Parce qu’ils sont plus affectifs","Parce qu’ils sont moins nombreux","Parce qu’ils garantissent une recommandation"]'::jsonb, 0, 'Les liens forts partagent la même information que nous : ils sont redondants.', 2),
    ('ef2450f3-7fc4-5ca1-a7b2-13e3092638b2'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Les liens forts relient des mondes sociaux séparés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les liens FAIBLES qui jouent ce rôle de pont.', 3),
    ('f2422434-fa2a-5958-8056-d8862213a433'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Qu’est-ce que le capital social ?', 'mcq', '["Les ressources accessibles grâce à son réseau de relations","Le capital financier d’une entreprise","Le patrimoine immobilier d’un ménage","Le niveau de diplôme atteint"]'::jsonb, 0, 'Il est inégalement réparti et convertible en avantages concrets.', 4),
    ('47277c6d-293e-5f26-a123-e75aa7c54d04'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Le capital social est également réparti entre les catégories sociales.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les cadres disposent de réseaux plus étendus, plus diversifiés et mieux placés.', 5),
    ('068541a1-2302-5c0a-86c3-1432a912ed03'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Les plateformes numériques suppriment l’homophilie dans les relations.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles la reproduisent, et les algorithmes de recommandation la renforcent souvent.', 6),
    ('fbaff068-318c-52f9-a4c2-68885c1beee0'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Comment un réseau dense favorise-t-il l’action collective ?', 'mcq', '["Il diffuse l’information et exerce une pression au conformisme","Il augmente le coût de l’engagement","Il rend les individus anonymes","Il supprime les intérêts divergents"]'::jsonb, 0, 'C’est un frein au comportement de passager clandestin décrit par Olson.', 7),
    ('17af6593-ef62-5145-a2c9-543517c2da42'::uuid, 'c410dc4d-987c-5d3f-a9ab-ebde68612d8d'::uuid, 'Un réseau social au sens sociologique se limite aux plateformes numériques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La notion est bien antérieure : elle désigne l’ensemble des relations d’un individu.', 8),
    ('54473853-6b06-5476-a964-df984e70300b'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Qu’est-ce que le contrôle social informel ?', 'mcq', '["Le contrôle exercé par l’entourage au moyen de sanctions diffuses","Le contrôle exercé par la police","Le contrôle des comptes d’une entreprise","La surveillance vidéo des espaces publics"]'::jsonb, 0, 'Regard, moquerie, réprobation : la sanction n’est pas codifiée.', 1),
    ('00398ae6-905e-5e81-9e7a-c1c76fecebce'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Le contrôle social se réduit à l’action de la police et de la justice.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le contrôle informel de l’entourage en est une part essentielle.', 2),
    ('b55d3870-d612-5c7d-8892-2beb5f8d667b'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Quel contrôle a reculé avec l’urbanisation et la mobilité ?', 'mcq', '["Le contrôle informel de proximité","Le contrôle judiciaire","Le contrôle technologique","Le contrôle administratif"]'::jsonb, 0, 'L’anonymat urbain a affaibli la surveillance du voisinage.', 3),
    ('8dc232fa-8c94-506d-b23a-2c4a69bca3dc'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Quelle autorité encadre l’usage des données personnelles en France ?', 'mcq', '["La CNIL","L’INSEE","Le Défenseur des droits","L’Autorité de la concurrence"]'::jsonb, 0, 'Elle veille au respect du RGPD et des libertés informatiques.', 4),
    ('15408862-f7f7-5045-b62a-a470f4fdd083'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Une même conduite peut être déviante dans une société et normale dans une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La déviance n’est pas une propriété de l’acte, mais du regard porté sur lui.', 5),
    ('39694895-8110-52bf-83f8-256c67429de2'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Quelle est la forme la plus efficace de contrôle social selon les sociologues ?', 'mcq', '["L’intériorisation des normes par la socialisation","L’amende","La prison","La vidéosurveillance"]'::jsonb, 0, 'Elle évite la transgression sans qu’aucune sanction n’ait à intervenir.', 6),
    ('3c859dfa-b94b-5fe6-bd24-2af9e66d4861'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Le contrôle social formel repose sur des sanctions codifiées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Amende, peine, sanction disciplinaire : elles sont écrites et prévisibles.', 7),
    ('cb747f08-da98-58bf-b15d-7da2430e5cff'::uuid, 'b70b12ea-b36a-57ff-9ad5-c41c47cf0e63'::uuid, 'Que change le contrôle technologique par rapport au contrôle traditionnel ?', 'mcq', '["Il est permanent, distant et souvent invisible","Il est plus affectif","Il concerne uniquement les entreprises","Il supprime le besoin de justice"]'::jsonb, 0, 'D’où le débat sur l’équilibre entre sécurité et libertés.', 8),
    ('b3cf89f8-317f-5464-bb98-e2b6b853d021'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Quelle est la différence entre déviance et délinquance ?', 'mcq', '["La délinquance transgresse une norme juridique, la déviance une norme sociale quelconque","Elles sont synonymes","La déviance est toujours pénalement sanctionnée","La délinquance concerne uniquement les mineurs"]'::jsonb, 0, 'Toute délinquance est déviante, mais toute déviance n’est pas délinquante.', 1),
    ('c6fba2c6-1012-50cc-9bfb-adc87d05a5df'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Qu’appelle-t-on anomie chez Durkheim ?', 'mcq', '["L’affaiblissement des normes collectives régulant les conduites","L’absence de police","La pauvreté économique","Le refus de voter"]'::jsonb, 0, 'La société ne parvient plus à réguler les aspirations individuelles.', 2),
    ('94270d7d-4ba9-5ca9-b3f5-c44cf2e83d00'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Selon Merton, la déviance naît d’un écart entre les buts valorisés et les moyens légitimes d’y accéder.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le cœur de sa typologie des cinq adaptations.', 3),
    ('a1a43541-dbe4-544a-a02a-933ac50ae7b4'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Comment Merton nomme-t-il l’adaptation qui poursuit le but socialement valorisé par des moyens illégitimes ?', 'mcq', '["L’innovation","Le ritualisme","L’évasion","La rébellion"]'::jsonb, 0, 'On garde le but — la réussite — mais on abandonne les moyens légitimes.', 4),
    ('dee96a2d-14c4-549a-aad2-8d014670fb21'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Que soutient Becker avec la théorie de l’étiquetage ?', 'mcq', '["La déviance résulte de la réaction sociale qui désigne un individu comme déviant","La déviance est innée","La déviance vient de la pauvreté","La déviance disparaît avec l’éducation"]'::jsonb, 0, 'Est déviant celui à qui l’étiquette a été appliquée avec succès.', 5),
    ('d4fce076-4fc5-5a4f-a13c-e360f1979c39'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'La carrière déviante décrit un processus en plusieurs étapes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Transgression, étiquetage, stigmatisation, entrée dans un groupe déviant.', 6),
    ('7f34982f-dcb4-5046-aba9-e5370d99c5f2'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Qu’est-ce qu’une prophétie auto-réalisatrice appliquée à la déviance ?', 'mcq', '["L’étiquette de déviant finit par produire le comportement qu’elle désigne","Une prédiction statistique de la délinquance","Une peine prononcée par anticipation","Un contrôle policier préventif"]'::jsonb, 0, 'La stigmatisation ferme les voies ordinaires et pousse vers le groupe déviant.', 7),
    ('9303413b-40ca-55c0-b6bf-c390cf645319'::uuid, '8e5adad8-30ee-5505-a8ce-117f212c489e'::uuid, 'Les théories de Merton et de Becker sont incompatibles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles éclairent deux moments différents : l’origine de la transgression et son traitement social.', 8),
    ('b4f21f6e-9cfc-5ac5-b629-f1d5812a3718'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Que mesure une enquête de victimation ?', 'mcq', '["Les atteintes subies déclarées par un échantillon de la population","Le nombre de condamnations prononcées","Le nombre de policiers en activité","Le sentiment d’insécurité uniquement"]'::jsonb, 0, 'Elle recense aussi ce qui n’a jamais fait l’objet d’une plainte.', 1),
    ('75c42b87-ee28-5714-ae44-6eaefd5518ff'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Qu’est-ce que le chiffre noir de la délinquance ?', 'mcq', '["L’écart entre la délinquance réelle et la délinquance enregistrée","Le nombre de crimes non élucidés","Le coût économique de la délinquance","Le taux de récidive"]'::jsonb, 0, 'Il varie énormément selon le type d’infraction.', 2),
    ('d042c8a5-60c5-527f-bae3-096fd31eba77'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Une hausse des plaintes prouve toujours une hausse de la délinquance réelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut traduire une meilleure propension des victimes à porter plainte.', 3),
    ('2d86cb91-c589-5a83-8e3e-a743d82fc265'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Pourquoi les statistiques policières dépendent-elles de l’activité des services ?', 'mcq', '["Parce que davantage de contrôles produisent mécaniquement plus d’infractions constatées","Parce que les policiers choisissent les chiffres publiés","Parce que les plaintes sont anonymes","Parce que la loi change chaque année"]'::jsonb, 0, 'C’est particulièrement net pour les infractions révélées par l’action des services.', 4),
    ('d98f03c9-9d35-528b-a6f6-0fc745b87abc'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Pour quelles infractions le chiffre noir est-il le plus faible ?', 'mcq', '["Les vols de voiture, dont la plainte est exigée par l’assurance","Les violences intrafamiliales","Les agressions sexuelles","La corruption"]'::jsonb, 0, 'Le dépôt de plainte y est quasi systématique.', 5),
    ('05e51587-29c6-53df-b5d1-765e1eddd2ab'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Les enquêtes de victimation couvrent mal les infractions sans victime directe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Trafic de stupéfiants ou corruption échappent à l’interrogation des victimes.', 6),
    ('57f1c1f1-be59-5bd4-9f37-714bd0df9d0e'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Que révèle la composition de la population carcérale ?', 'mcq', '["Un cumul d’expositions inégales à la transgression et d’un traitement pénal sélectif","La propension naturelle de certains groupes au crime","L’efficacité de la police","L’absence de biais dans la justice"]'::jsonb, 0, 'La délinquance en col blanc est moins détectée et moins sanctionnée.', 7),
    ('ad47f008-c0c0-5e65-893d-ec202e0e9b6b'::uuid, '3742f2c3-41ce-5a0b-b304-873df61276e3'::uuid, 'Un changement de législation peut modifier les statistiques de la délinquance sans que les comportements changent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un acte peut entrer dans le champ pénal ou en sortir d’une année sur l’autre.', 8),
    ('c814c1da-79bf-53b4-a9be-26f319e45f7c'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Qu’est-ce que l’espace public au sens de Habermas ?', 'mcq', '["Un espace de discussion des affaires communes par des particuliers","Les rues et les places d’une ville","Les bâtiments appartenant à l’État","Les médias publics"]'::jsonb, 0, 'Salons, cafés et presse en constituent la forme historique.', 1),
    ('ccff07aa-52c5-5dc3-91ad-7906171ff5e1'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'L’opinion publique est une donnée naturelle, indépendante des instruments qui la mesurent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une construction historique et sociale, façonnée par ses instruments.', 2),
    ('5cee5d06-6e4b-5b13-a86b-f11646fc353d'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Sur quelle méthode repose le plus souvent la construction d’un échantillon de sondage ?', 'mcq', '["La méthode des quotas","Le recensement exhaustif","Le volontariat sur internet","Le tirage au sort des électeurs inscrits"]'::jsonb, 0, 'On reproduit dans l’échantillon la structure de la population.', 3),
    ('cbf9bedd-5e0f-59ad-8fee-e3eb3d5d0910'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Que critique Bourdieu en écrivant « l’opinion publique n’existe pas » ?', 'mcq', '["Les postulats implicites du sondage d’opinion","L’existence des débats politiques","Le suffrage universel","La liberté de la presse"]'::jsonb, 0, 'Il conteste l’idée que chacun a un avis sur tout et que toutes les opinions se valent.', 4),
    ('dbd752a5-d6ef-5aa7-9e3e-aa0da44d7e81'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'La formulation d’une question de sondage peut modifier le résultat obtenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un des biais les mieux documentés, avec l’ordre des questions.', 5),
    ('b87abf08-b855-5fa1-930c-105e0c67f4b4'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Qu’est-ce que la marge d’erreur d’un sondage ?', 'mcq', '["L’intervalle dans lequel se situe probablement la valeur réelle","Le nombre de personnes n’ayant pas répondu","Le taux de refus de l’enquête","L’écart entre deux instituts"]'::jsonb, 0, 'Un écart inférieur à cette marge ne peut pas être interprété comme une différence réelle.', 6),
    ('02dea085-5989-5eae-a850-73770d79dadd'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Qu’appelle-t-on effet bandwagon ?', 'mcq', '["Le ralliement d’électeurs au candidat annoncé gagnant","Le refus de répondre aux sondages","La sous-estimation des petits partis","L’abstention des jeunes"]'::jsonb, 0, 'Le sondage agit alors sur le comportement qu’il prétendait seulement mesurer.', 7),
    ('a4a64f98-b7f5-55b3-ac27-cb0d5ca8b62b'::uuid, 'bcb99eba-d1f7-5b19-b4f6-5f4bb0f4b5bf'::uuid, 'Les réseaux sociaux donnent à chacun une visibilité équivalente dans le débat public.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La visibilité y est très concentrée, sur quelques comptes et quelques contenus.', 8),
    ('1a5aa944-c35a-5d11-9357-c3cded16980d'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'Que sont les « variables lourdes » du vote ?', 'mcq', '["L’appartenance de classe, la religion et le lieu de résidence","L’âge, le sexe et la taille du ménage","Le revenu, l’épargne et le patrimoine","Le programme, le débat et la campagne"]'::jsonb, 0, 'Ce sont les caractéristiques sociales les plus prédictives du vote.', 1),
    ('1b14cbba-03b2-5249-b2b7-b665a4c7e5de'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'La pratique religieuse régulière reste une variable fortement prédictive du vote.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’une des plus robustes, même si son poids global recule avec la déchristianisation.', 2),
    ('3746f2d6-175e-5f1e-8186-870525e99dfa'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'Qu’est-ce que le vote sur enjeux ?', 'mcq', '["Un vote déterminé par un problème particulier du moment","Un vote dicté par l’appartenance de classe","Un vote héréditaire","Un vote obligatoire"]'::jsonb, 0, 'Il progresse à mesure que les variables lourdes s’affaiblissent.', 3),
    ('ae08ed16-f6ad-5c24-bd04-bf6271f5acbd'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'La volatilité électorale désigne…', 'mcq', '["le fait de changer de vote d’une élection à l’autre","l’instabilité des sondages","le taux d’abstention","le nombre de candidats en lice"]'::jsonb, 0, 'Elle est l’un des signes de l’affaiblissement des ancrages partisans.', 4),
    ('ebbf496f-351e-5749-8734-f3e68e0909ed'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'L’abstention traduit toujours un désintérêt pour la politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’abstention « dans le jeu » est le fait d’électeurs politisés qui protestent.', 5),
    ('956adaaf-fcbf-5b7f-8c08-58fe784c30e7'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'À quel type de scrutin l’abstention est-elle historiquement la plus faible en France ?', 'mcq', '["L’élection présidentielle","Les élections européennes","Les élections régionales","Les élections municipales des grandes villes"]'::jsonb, 0, 'Elle est perçue comme l’élection décisive du système politique français.', 6),
    ('d38fbf1b-6eb0-5d88-87cc-c5652ede05e9'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'Qu’a montré Lazarsfeld dès 1944 ?', 'mcq', '["Que le vote se prédit mieux par les caractéristiques sociales que par la campagne","Que les campagnes déterminent le résultat","Que le vote est totalement imprévisible","Que les sondages sont sans effet"]'::jsonb, 0, 'C’est l’acte de naissance de la sociologie électorale quantitative.', 7),
    ('ab832d86-c3d8-512e-bb8c-173f943bc25b'::uuid, '3c65beab-6c94-5c6d-b9df-77e869a69dd3'::uuid, 'L’inscription dans des réseaux associatifs augmente la probabilité de voter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La mobilisation par l’entourage est un ressort documenté de la participation.', 8),
    ('026683bf-de2b-5008-9c6f-a8266f2725e4'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Qu’est-ce que la mutualisation d’un risque ?', 'mcq', '["Le partage du coût d’un dommage entre un grand nombre de personnes","La suppression du risque","L’assurance d’un seul individu","L’épargne de précaution individuelle"]'::jsonb, 0, 'C’est le principe commun à l’assurance et à la protection sociale.', 1),
    ('2320c156-ecc2-5dbd-9f5e-5bd73b75d788'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Quelle logique verse une prestation sous condition de ressources, financée par l’impôt ?', 'mcq', '["La logique d’assistance","La logique d’assurance","La logique de cotisation","La logique contributive"]'::jsonb, 0, 'Elle est dite beveridgienne ; le RSA en relève.', 2),
    ('253f110b-ba29-559b-a866-4cb1fa66fbd0'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Le système français de protection sociale relève d’une seule logique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est hybride : assurantiel à l’origine, il s’est élargi vers l’assistance.', 3),
    ('2e4f9feb-c5f9-5d32-ad21-0aa79d4f0b33'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Qu’est-ce que l’aléa moral en assurance ?', 'mcq', '["Le fait qu’être couvert modifie le comportement de l’assuré","Le mensonge sur son état de santé à la souscription","Le refus d’assurer un risque élevé","La hausse des primes avec l’âge"]'::jsonb, 0, 'Franchises et délais de carence servent à le limiter.', 4),
    ('b9ace07a-2eb8-512c-b7d7-e681bc3dc2be'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Pourquoi rendre l’affiliation obligatoire limite-t-il la sélection adverse ?', 'mcq', '["Parce que les bons risques ne peuvent pas se retirer du système","Parce que les primes deviennent plus élevées","Parce que l’État contrôle les assureurs","Parce que les prestations sont plus généreuses"]'::jsonb, 0, 'Sans obligation, les bons risques partent et la prime des restants explose.', 5),
    ('59f94793-2a25-5f50-9ba9-916bbd70c90b'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'La famille ne joue plus aucun rôle dans la protection contre les risques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste un producteur majeur de protection, notamment pour la dépendance.', 6),
    ('3c466869-220d-51c9-b8a5-2f410d5c3aa3'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'Environ quelle part du PIB français la protection sociale représente-t-elle ?', 'mcq', '["Environ un tiers","Environ 5 %","Environ la moitié","Environ 10 %"]'::jsonb, 0, 'C’est l’un des niveaux les plus élevés de l’OCDE.', 7),
    ('9effd7f4-3881-58c9-8f9d-3414c783b1e9'::uuid, 'd5d0365b-f251-5a67-a279-4339e383484d'::uuid, 'La redistribution réduit sensiblement l’écart entre les revenus les plus élevés et les plus modestes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le rapport interdécile est nettement plus faible après prélèvements et prestations.', 8),
    ('ff9fb6b4-2a3c-5389-beb0-cab9deba0ca7'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Quelle catégorie d’entreprises est de loin la plus nombreuse en France ?', 'mcq', '["Les microentreprises","Les grandes entreprises","Les ETI","Les entreprises publiques"]'::jsonb, 0, 'Elles emploient moins de 10 salariés et constituent l’essentiel des unités.', 1),
    ('3d03a128-129e-5b5c-86b8-822b582635d3'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Les grandes entreprises concentrent une part importante de l’emploi salarié malgré leur faible nombre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Peu nombreuses, elles pèsent lourd dans l’emploi, le chiffre d’affaires et l’export.', 2),
    ('2f1fd0f5-0a70-539a-89ad-cd67d432bd5b'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Qu’est-ce qui caractérise l’entrepreneur chez Schumpeter ?', 'mcq', '["Il innove et déclenche la destruction créatrice","Il possède le capital","Il gère les salariés au quotidien","Il assume les tâches administratives"]'::jsonb, 0, 'Nouveau produit, nouveau procédé, nouveau marché, nouvelle organisation.', 3),
    ('76b56cfe-b6b1-5a8f-bfd5-f0c0b2ffe558'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Selon Knight, l’entrepreneur assume…', 'mcq', '["l’incertitude, c’est-à-dire un risque non calculable","un risque toujours assurable","la seule responsabilité juridique","la gestion comptable"]'::jsonb, 0, 'C’est ce qui justifie, à ses yeux, le profit.', 4),
    ('779434da-fbc3-57f6-a688-7103640d487f'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Dans une coopérative, le pouvoir est proportionnel au capital détenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La règle est le plus souvent « une personne, une voix ».', 5),
    ('7cad6d67-ecc5-5424-be2b-52084f812da8'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Qu’apporte le statut de société par rapport à l’entreprise individuelle ?', 'mcq', '["La séparation entre le patrimoine de l’entreprise et celui des propriétaires","L’exonération d’impôt","L’absence de comptabilité","La garantie de bénéfices"]'::jsonb, 0, 'C’est la protection du patrimoine personnel qui distingue les deux.', 6),
    ('a794e9e4-bb65-568a-9e24-fff260e1431b'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'Que regroupe l’économie sociale et solidaire ?', 'mcq', '["Coopératives, mutuelles, associations et fondations","Les seules entreprises publiques","Les entreprises cotées en Bourse","Les micro-entreprises uniquement"]'::jsonb, 0, 'Leur point commun : le profit n’est pas la finalité de l’activité.', 7),
    ('b03c5813-ea28-53f7-8eb6-0c895e531b1a'::uuid, 'cec076ca-be54-57b1-9f5c-97b8a7905ca8'::uuid, 'L’origine sociale et le réseau influencent la probabilité de créer une entreprise.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Capital économique, capital social et capital culturel pèsent sur la création et la survie.', 8),
    ('233023bb-e218-5ef0-86bd-df7692a1a5f0'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Sur quoi repose le taylorisme ?', 'mcq', '["La division verticale et horizontale du travail et le chronométrage","L’autonomie des équipes","Les flux tendus","La polyvalence des salariés"]'::jsonb, 0, 'Concevoir et exécuter sont séparés, les tâches sont parcellisées.', 1),
    ('c064492f-9586-5095-9225-0f53da77a851'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Qu’ajoute le fordisme au taylorisme ?', 'mcq', '["La chaîne, la standardisation et des salaires élevés","La qualité totale","Le juste-à-temps","La suppression de la hiérarchie"]'::jsonb, 0, 'Le five dollars day permet aussi d’écouler la production de masse.', 2),
    ('9db87477-fd85-59ba-b33c-2df62a38663a'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Le toyotisme repose sur la production en flux tendus et la qualité totale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il répond aux limites du fordisme par la flexibilité et l’implication des équipes.', 3),
    ('8bd41104-ccb1-5af0-b54d-2559368efab6'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Qu’est-ce qu’une zone d’incertitude chez Crozier ?', 'mcq', '["Une marge de manœuvre qui donne du pouvoir à un acteur, même subalterne","Un risque financier non couvert","Une clause floue du contrat de travail","Une période d’essai"]'::jsonb, 0, 'Le pouvoir ne se lit pas seulement dans l’organigramme.', 4),
    ('6caea87a-01c4-5300-844b-6b4b3cca9173'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Les conflits du travail sont nécessairement le signe d’un dysfonctionnement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont une expression normale d’intérêts divergents, et une voie de régulation.', 5),
    ('b9cc518e-a62c-573c-8e07-56ed1528949b'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Qu’est-ce que la relation d’agence dans la gouvernance d’entreprise ?', 'mcq', '["La divergence d’intérêts et d’information entre dirigeants et actionnaires","Le lien entre l’entreprise et ses clients","Le contrat entre deux entreprises","Le mandat des représentants du personnel"]'::jsonb, 0, 'Elle justifie les mécanismes de contrôle des dirigeants.', 6),
    ('e143dbe4-2b1b-56a6-a4b9-53a2d55bb649'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Qui sont les parties prenantes d’une entreprise ?', 'mcq', '["Tous ceux qui sont affectés par son activité : salariés, clients, fournisseurs, territoire","Les seuls actionnaires","Les seuls dirigeants","Les seuls créanciers"]'::jsonb, 0, 'La gouvernance partenariale les prend en compte face aux seuls actionnaires.', 7),
    ('b5a98177-6d22-59ef-806c-3d1d4fe793b2'::uuid, '0e5a617c-1fa0-554d-8ea4-ddee111bd542'::uuid, 'Les formes du conflit du travail ont évolué vers des expressions plus individuelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Absentéisme, turnover et recours prud’homal ont pris de l’importance face aux grèves longues.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('ses');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('ses')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 268 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 268 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
